function AnalyticsPage({productPage=false}={}) {
  const profile=useValue(host.state.profile)
  const gateway=useValue(host.state.gateway)
  const connection=useValue(host.state.connectionId || $none)
  const scope=analyticsScope(profile,gateway,connection)
  const states=useValue($analytics)
  const state=states[scope] || analyticsInitialState()
  // Dispatch reads the latest atom, so rapid actions never borrow a stale render's filters.
  const dispatch=action=>analyticsDispatch(scope,action)
  const query=useQuery(analyticsQuery(state.days,state.filters,scope))
  return jsx(AnalyticsDashboard,{data:query.data,state,dispatch,query,scope,profile,productPage})
}


/* ------------------------------------------------- billing & pricing settings */

/** Evidence rows, each carrying its own basis so nothing looks confirmed. */
function billingEvidence(billing, t = needsAttentionEn) {
  const ev = billing?.evidence || {}
  const rows = [
    ['provider_reported', t('billEvProviderLabel'), t('billEvProviderExplain'), t('billEvProviderEmpty')],
    ['api_equivalent', t('billEvApiLabel'), t('billEvApiExplain'), t('billEvApiEmpty')],
    ['credits_consumed', t('billEvCreditsLabel'), t('billEvCreditsExplain'), t('billEvCreditsEmpty')],
    ['incremental_cash', t('billEvCashLabel'), t('billEvCashExplain'), t('billEvCashEmpty')],
    ['subscription_fee', t('billEvFeeLabel'), t('billEvFeeExplain'), t('billEvFeeEmpty')]
  ]
  return rows.map(([key, label, explanation, empty]) => ({
    key, label, explanation, empty,
    usd: ev[key]?.usd ?? null,
    basis: ev[key]?.basis || 'none',
    source: ev[key]?.source || ''
  }))
}

function profileDraftErrors(draft, t = needsAttentionEn) {
  const errors = []
  if (!draft) return [t('advRulesErrNoDraft')]
  if (!String(draft.id || '').trim()) errors.push(t('advRulesErrName'))
  if (!String(draft.provider || '').trim()) errors.push(t('advRulesErrProvider'))
  if (!String(draft.kind || '')) errors.push(t('advRulesErrKind'))
  if (draft.kind === 'unknown' && draft.monthly_fee_usd) errors.push(t('advRulesErrUnknownFee'))
  if (draft.monthly_fee_usd != null && draft.monthly_fee_usd !== '' && !Number.isFinite(Number(draft.monthly_fee_usd))) errors.push(t('advRulesErrFeeNumber'))
  if (draft.allowance_usd != null && draft.allowance_usd !== '' && !Number.isFinite(Number(draft.allowance_usd))) errors.push(t('advRulesErrAllowanceNumber'))
  return errors
}

function billingNumberStep(options = {}) {
  return options.step ?? (options.type === 'number' ? 'any' : undefined)
}

function profilePayload(draft) {
  const number = value => (value === '' || value == null ? undefined : Number(value))
  const payload = {
    id: String(draft.id).trim(),
    provider: String(draft.provider || '').trim() || undefined,
    model: String(draft.model || '').trim() || undefined,
    kind: draft.kind,
    monthly_fee_usd: number(draft.monthly_fee_usd),
    allowance_usd: draft.allowance_model ? draft.original_scalar_allowance : number(draft.allowance_usd),
    overage_paid: Boolean(draft.overage_paid),
    count_credits_as_spend: Boolean(draft.count_credits_as_spend),
    effective_from: draft.effective_from || undefined,
    effective_to: draft.effective_to || undefined,
    billing_cycle: draft.cycle_day ? { ...(draft.billing_cycle || {}), day: Number(draft.cycle_day) } : undefined,
    currency: draft.currency || undefined,
    label: draft.label || undefined,
    account: draft.account || undefined,
    rate_override: draft.rate_input !== '' && draft.rate_input != null && draft.rate_output !== '' && draft.rate_output != null ? {
      ...(draft.rate_override || {}), input: Number(draft.rate_input), output: Number(draft.rate_output),
      ...(draft.rate_cache !== '' && draft.rate_cache != null ? { cache_read: Number(draft.rate_cache) } : {})
    } : undefined,
    rev: draft.rev || undefined
  }
  if (payload.rate_override && (draft.rate_cache === '' || draft.rate_cache == null)) delete payload.rate_override.cache_read
  const allowances = { ...(draft.allowances || {}) }
  if (draft.original_allowance_model && draft.original_allowance_model !== draft.allowance_model)
    delete allowances[draft.original_allowance_model]
  const allowanceModel = String(draft.allowance_model || '').trim()
  if (allowanceModel) {
    if (draft.allowance_usd === '' || draft.allowance_usd == null) delete allowances[allowanceModel]
    else allowances[allowanceModel] = Number(draft.allowance_usd)
  }
  if (Object.keys(allowances).length) payload.allowances = allowances
  return Object.fromEntries(Object.entries(payload).filter(([, value]) => value !== undefined))
}

const KIND_CHOICES = [
  ['api', 'Pay as you go'],
  ['prepaid', 'Prepaid wallet'],
  ['custom', 'Custom token rates'],
  ['unknown', 'Unknown']
]
/** Billing-rule kinds to their I18N choice labels. KIND_CHOICES keeps the canonical English. */
const KIND_LABEL_KEYS = {
  api: 'billKindApi',
  prepaid: 'billKindPrepaid',
  custom: 'billKindCustom',
  unknown: 'billKindUnknown',
}

const $billingDraft = atom(null)
const $billingPresentation = atom('both')

/** Which figures each presentation mode leads with. */
function evidenceForMode(rows, mode) {
  const keys = mode === 'spend' ? ['provider_reported', 'incremental_cash', 'subscription_fee']
    : mode === 'api' ? ['api_equivalent']
    : ['provider_reported', 'api_equivalent', 'credits_consumed', 'incremental_cash', 'subscription_fee']
  return rows.filter(row => keys.includes(row.key))
}
/** Initial tab from the host hash. Settings is matched before billing so a
 * settings-section hash (e.g. `#settings-billing`) selects Settings. */
function ledgerTabForHash(hash) {
  const value = String(hash || '')
  if (/memberships?/.test(value)) return 'memberships'
  if (/settings/.test(value)) return 'settings'
  if (/billing/.test(value)) return 'costs'
  if (/usage/.test(value)) return 'usage'
  if (/costs/.test(value)) return 'costs'
  if (/reports/.test(value)) return 'reports'
  if (/news/.test(value)) return 'news'
  return 'overview'
}
const $ledgerTab = atom(typeof location !== 'undefined' ? ledgerTabForHash(location.hash) : 'overview')
const $billingNotice = atom(null)
const $billingProfiles = atom({ profiles: [], loading: true, error: '' })

function billingQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'billing-profiles', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('This desktop build has no plugin backend bridge.')
      const result = await rest('/billing/profiles')
      if (!result || result.ok === false || result.error) throw new Error(result?.error || 'Billing profiles are unavailable.')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      return { ...result, identity }
    },
    retry: false, staleTime: 10_000
  }
}

async function billingWrite(method, path, body, transport = rest) {
  if (typeof transport !== 'function') throw new Error('No plugin backend bridge.')
  // ctx.rest takes `body` as a value and serialises it in the desktop main
  // process. Passing a pre-stringified body double-encodes it, which FastAPI
  // sees as a string rather than an object (422 "Input should be a valid
  // dictionary").
  const result = await transport(path, { method, ...(body ? { body } : {}) })
  if (!result || result.ok === false) throw new Error(result?.detail || result?.error || 'The profile could not be saved.')
  return result
}

/** Concise, non-technical messages — never a raw FastAPI/Pydantic payload. */
function billingErrorMessage(error, t = needsAttentionEn) {
  const raw = typeof error?.message === 'string' ? error.message : ''
  if (/conflict|409/i.test(raw)) return t('billErrConflict')
  if (/valid dictionary|422|validation/i.test(raw)) return t('billErrValidation')
  if (/401|unauthori/i.test(raw)) return t('billErrAuth')
  if (/404/i.test(raw)) return t('billErrUnavailable')
  return t('billErrSave')
}

function billingSummaryQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'billing-summary', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('This desktop build has no plugin backend bridge.')
      const result = await rest('/billing/summary')
      if (!result || result.ok === false) throw new Error(result?.error || 'Billing summary is unavailable.')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      return { ...result, identity }
    },
    retry: false, staleTime: 30_000
  }
}

function economicsQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'economics-summary', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('This desktop build has no plugin backend bridge.')
      const result = await rest('/economics/summary?days=30&trend_months=6')
      if (!result || result.ok === false) throw new Error(result?.error || 'Subscription economics is unavailable.')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      return { ...result, identity }
    },
    retry: false, staleTime: 30_000
  }
}

function fxQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'fx-rates', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('This desktop build has no plugin backend bridge.')
      const result = await rest('/membership/fx')
      if (!result || result.ok === false) throw new Error(result?.detail || result?.error || 'FX rates are unavailable.')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      return { ...result, identity }
    },
    retry: false, staleTime: 30_000
  }
}

async function fxWrite(rates, transport = rest) {
  if (typeof transport !== 'function') throw new Error('No plugin backend bridge.')
  const result = await transport('/membership/fx', { method: 'PUT', body: { rates } })
  if (!result || result.ok === false) throw new Error(result?.detail || result?.error || 'The rates were not saved.')
  return result
}

/**
 * Membership data changed, so the economics comparison built on it is stale.
 * Best-effort: freshness must never break the save flow that triggered it.
 */
async function invalidateEconomicsFor(identity) {
  try {
    await queryClient.invalidateQueries({ queryKey: [ID, 'economics-summary', identity] })
  } catch {
    /* the cached comparison simply stays until its stale time elapses */
  }
}

async function invalidateWeatherFor(identity) {
  try {
    await queryClient.invalidateQueries({ queryKey: [ID, 'allowance-weather', identity] })
  } catch {
    /* the cached verdicts simply stay until their stale time elapses */
  }
}

/** Billing profiles feed the economics comparison and the weather pools alike. */
async function invalidateBillingDependentsFor(identity) {
  await invalidateEconomicsFor(identity)
  await invalidateWeatherFor(identity)
}

/** Transport markers that must never reach the user verbatim. The numeric arm matches HTTP statuses (400-599) only, so validation details mentioning ordinary values such as 255 characters still pass through. */
const FX_TRANSPORT = /\b[45]\d{2}\b|timeout|timed out|network|failed to fetch|fetch failed|connection|econn|socket|abort/i

/** FX failures carry the server's validation sentence; anything else is generic. */
function fxErrorMessage(t, error) {
  const raw = typeof error?.message === 'string' ? error.message : ''
  if (/conflict|409/i.test(raw)) return t('fxErrConflict')
  if (/401|unauthori/i.test(raw)) return t('fxErrSession')
  if (/404/i.test(raw)) return t('fxErrUnavailable')
  if (/422|validation/i.test(raw)) {
    // Only the server's plain validation sentence passes through: a raw
    // transport message with no colon, or detail still carrying a status,
    // fails closed to the generic rejection sentence.
    const detail = raw.replace(/^.*?:\s*/, '')
    if (detail && detail !== raw && !FX_TRANSPORT.test(detail)) return detail
    return t('fxErrRejected')
  }
  if (!raw) return t('fxErrSave')
  // Transport failures (status codes, timeouts, network errors) never reach
  // the user verbatim; only the server's plain validation detail passes.
  if (FX_TRANSPORT.test(raw)) {
    return t('fxErrSave')
  }
  return raw
}

/** UTC calendar day for renewal dates, which are UTC midnights. */
function fmtDay(value) {
  if (value === null || value === undefined || value === '') return '—'
  const when = new Date(value)
  if (Number.isNaN(when.getTime())) return '—'
  return when.toISOString().slice(0, 10)
}

/** Short human status for an economics comparison. */
function econStatusLabel(t, status) {
  return status === 'ok' ? t('econStatusOk') : status === 'partial' ? t('econStatusPartial') : t('econStatusUnavailable')
}

/** Static backend note codes from wolfmark_ledger/analytics.py (ov_note_gap carries params). */
const ANALYTICS_NOTE_KEYS = {
  ov_note_window: 'ovNoteWindow',
  ov_note_options: 'ovNoteOptions',
  ov_note_prices: 'ovNotePrices',
  ov_note_errors: 'ovNoteErrors',
  ov_note_cache: 'ovNoteCache',
  ov_note_fallback: 'ovNoteFallback',
  ov_note_economics: 'ovNoteEconomics',
  ov_note_billing: 'ovNoteBilling',
  ov_note_previous: 'ovNotePrevious',
}

/** Economics gap reasons from analytics._call_economics; unknown reasons pass through raw. */
const OV_GAP_REASON_KEYS = {
  call_failed: 'ovGapCallFailed',
  usage_missing: 'ovGapUsageMissing',
  provider_unidentified: 'ovGapProviderMissing',
  model_unidentified: 'ovGapModelMissing',
  cache_provenance_unknown: 'ovGapCacheProvenance',
  provider_price_catalogue_missing: 'ovGapProviderPrice',
  price_evidence_missing: 'ovGapModelPrice',
  rate_unavailable: 'ovGapRateUnavailable',
  tier_rate_unavailable: 'ovGapTierRate',
  missing_base_rate: 'ovGapMissingBaseRate',
  missing_cache_read_rate: 'ovGapMissingCacheRead',
  missing_cache_write_rate: 'ovGapMissingCacheWrite',
}

function analyticsGapReasonLabel(reason, t) {
  const key = OV_GAP_REASON_KEYS[reason]
  return key ? t(key) : reason
}

/** One analytics note from its note_codes entry; the English note is the fallback. */
function analyticsNoteText(entry, fallback, t) {
  const params = entry?.params
  if (entry?.code === 'ov_note_gap' && params && typeof params === 'object'
      && params.count !== undefined && params.reason !== undefined)
    return t('ovNoteGap', params.count, analyticsGapReasonLabel(params.reason, t))
  const key = entry ? ANALYTICS_NOTE_KEYS[entry.code] : null
  return key ? t(key) : fallback
}

/** Index-aligned analytics notes from note_codes; entries without a known code pass through. */
function analyticsNotesText(notes, codes, t) {
  const list = Array.isArray(notes) ? notes : []
  const aligned = Array.isArray(codes) ? codes : []
  return list.map((note, index) => {
    const entry = aligned[index]
    if (!entry || typeof entry !== 'object') return note
    return analyticsNoteText(entry, note, t)
  })
}

/** Static backend note codes from wolfmark_ledger/economics.py (unpriced/no_fx/fx_error carry params). */
const ECON_NOTE_KEYS = {
  econ_head_no_fees: 'econHeadNoFees',
  econ_head_incomparable: 'econHeadIncomparable',
  econ_head_partial: 'econHeadPartial',
  econ_head_ok: 'econHeadOk',
  econ_group_unknown_currency: 'econGroupUnknownCurrency',
  econ_group_missing: 'econGroupMissing',
  econ_group_partial: 'econGroupPartial',
  econ_group_window_history_missing: 'econGroupWindowHistory',
  econ_group_insufficient_history: 'econGroupHistory',
  econ_unattributed: 'econUnattributed',
  econ_ambiguous: 'econAmbiguous',
}

/** One economics note from its note_codes entry; the English note is the fallback. */
function econNoteText(entry, fallback, t) {
  const params = (entry && typeof entry.params === 'object' && entry.params) || {}
  const code = entry?.code
  if ((code === 'econ_head_unpriced' || code === 'econ_group_unpriced') && params.count !== undefined)
    return t(code === 'econ_head_unpriced' ? 'econHeadUnpriced' : 'econGroupUnpriced', params.count)
  if (code === 'econ_group_no_fx' && params.currency !== undefined)
    return t('econGroupNoFx', params.currency)
  if (code === 'econ_head_fx_error' && params.error !== undefined)
    return t('econHeadFxError', params.error)
  if (code === 'econ_group_window_history_missing')
    return t('econGroupWindowHistory', Number.isSafeInteger(params.count) && params.count >= 0
      ? params.count : null)
  const key = code ? ECON_NOTE_KEYS[code] : null
  return key ? t(key) : fallback
}

/** Index-aligned economics notes from note_codes; entries without a known code pass through. */
function econNotesText(notes, codes, t) {
  const list = Array.isArray(notes) ? notes : []
  const aligned = Array.isArray(codes) ? codes : []
  return list.map((note, index) => {
    const entry = aligned[index]
    if (!entry || typeof entry !== 'object') return note
    return econNoteText(entry, note, t)
  })
}

/** Singular economics note (unattributed/ambiguous note_code); raw note is the fallback. */
function econSingularNoteText(section, t) {
  const fallback = section?.note || ''
  const key = section ? ECON_NOTE_KEYS[section.note_code] : null
  return key ? t(key) : fallback
}

const ECON_EXPLANATION_KEYS = {
  api_only: 'econExplApiOnly',
  prepaid: 'econExplPrepaid',
  unconfirmed: 'econExplUnconfirmed',
}

/** Non-subscription account explanation from the stable arrangement; raw text is the fallback. */
function econExplanationText(row, t) {
  const fallback = row?.explanation || ''
  const key = row ? ECON_EXPLANATION_KEYS[row.arrangement] : null
  return key ? t(key) : fallback
}

/** One line for a usage value and its pricing coverage. */
function econCoverageLabel(t, usage) {
  if (!usage || (!num(usage.calls) && !num(usage.tokens))) return t('econNoUsage')
  if (usage.list_usd == null) return t('econNoPrice')
  if (usage.coverage == null) return t('econCoverageUnknown')
  const pct = Math.round(usage.coverage * 100)
  // Coverage rounds to whole percent: only the exact unpriced count can
  // certify fully priced, matching the backend status in the same cell.
  // A rounded 100% with unpriced tokens left is "nearly all", never exact.
  if (pct >= 100) return num(usage.unpriced_tokens) > 0 || num(usage.unpriced_calls) > 0
    ? t('econNearlyAllPriced') : t('econFullyPriced')
  return t('econPricedPct', pct)
}

function econBlockerText(blocker, t) {
  const code = blocker?.code
  if (code === 'subscription_fee_missing') return t('econBlockFeeMissing')
  if (code === 'dated_fx_rate_missing') return t('econBlockFxMissing', blocker.currency || 'currency')
  if (code === 'window_fee_history_missing') return t('econBlockWindowHistory')
  if (code === 'window_fee_allocation_unavailable') return t('econBlockWindowUnavailable')
  if (code === 'no_usage_recorded') return t('econBlockNoUsage')
  if (code === 'insufficient_comparison_history') return t('econBlockHistory')
  if (code === 'provider_unidentified' || code === 'provider_not_recorded') return t('econBlockProviderMissing')
  if (code === 'model_unidentified') return t('econBlockModelMissing')
  if (code === 'provider_price_catalogue_missing' || code === 'provider_not_in_catalogue') return t('econBlockProviderPrice')
  if (code === 'price_evidence_missing' || code === 'model_not_in_catalogue') return t('econBlockModelPrice')
  if (code === 'historical_ownership_billing_rule_incomplete') return t('econBlockOwnership')
  if (code === 'usage_price_incomplete' || code === 'usage_unknown' || code === 'usage_missing') return t('econBlockUsageEvidence')
  if (code === 'missing_base_rate') return t('econBlockBaseRate')
  if (code === 'tier_rate_unavailable') return t('econBlockTierRate')
  if (['cache_rate_unavailable', 'missing_cache_rate', 'missing_cache_read_rate',
    'missing_cache_write_rate'].includes(code)) return t('econBlockCacheRate')
  return code ? t('econBlockGeneric', code) : t('econBlockGeneric', t('econBlockUnknown'))
}

function econBlockerDestination(blocker) {
  const code = blocker?.code
  if (['subscription_fee_missing', 'historical_ownership_billing_rule_incomplete',
    'window_fee_history_missing', 'window_fee_allocation_unavailable'].includes(code)) return 'memberships'
  if (code === 'dated_fx_rate_missing') return 'fx'
  if (['no_usage_recorded', 'insufficient_comparison_history', 'provider_unidentified',
    'provider_not_recorded', 'model_unidentified', 'usage_price_incomplete', 'usage_unknown', 'usage_missing'].includes(code)) return 'usage'
  if (['provider_price_catalogue_missing', 'provider_not_in_catalogue', 'price_evidence_missing',
    'model_not_in_catalogue', 'missing_base_rate', 'tier_rate_unavailable', 'cache_rate_unavailable',
    'missing_cache_rate', 'missing_cache_read_rate', 'missing_cache_write_rate'].includes(code)) return 'settings'
  return null
}

function econBlockerActionLabel(destination, t) {
  return destination === 'memberships' ? t('econActionMemberships')
    : destination === 'fx' ? t('econActionFx')
    : destination === 'usage' ? t('econActionUsage')
    : destination === 'settings' ? t('econActionPricing') : null
}

function openEconomicsDestination(destination, onOpenFx) {
  if (destination === 'fx') return onOpenFx?.()
  if (destination) goLedgerTab(destination)
}

function EconomicsBlockers({ blockers = [], notes = [], t, onOpenFx }) {
  const visibleNotes = Array.isArray(notes) ? notes : []
  const visibleBlockers = Array.isArray(blockers) ? blockers : []
  if (!visibleNotes.length && !visibleBlockers.length) return null
  return jsxs('ul', { className: 'wm-econ-notes wm-econ-blockers', children: [
    ...visibleNotes.map((note, index) => jsx('li', { children: note }, `note-${index}`)),
    ...visibleBlockers.map((blocker, index) => {
      const destination = econBlockerDestination(blocker)
      return jsxs('li', { children: [
        jsx('span', { children: `${blocker.account_id || ''}${blocker.account_id ? ': ' : ''}${econBlockerText(blocker, t)}` }),
        destination ? jsx('button', { type: 'button', className: 'wm-source-link wm-econ-action',
          onClick: () => openEconomicsDestination(destination, onOpenFx),
          children: econBlockerActionLabel(destination, t) }) : null
      ].filter(Boolean) }, `${blocker.code || 'unknown'}-${index}`)
    })
  ] })
}

function econMoneyValue(amount, currency, complete = true) {
  const money = fmtMoney(amount, currency)
  if (!money || (!complete && finiteValue(amount) === 0)) return '—'
  return complete ? money : `≥${money}`
}

/** Window-allocated expenditure lines, one per currency — never summed here. */
function econWindowLines(fees, groups = []) {
  const rows = Array.isArray(fees) ? fees : []
  if (!rows.length) return ['—']
  const completeness = new Map((groups || []).map(group => [group.currency, group.window_fee_complete !== false]))
  return rows.map(({ amount, currency }) => econMoneyValue(amount, currency, completeness.get(currency) !== false))
}

/** Display span of the reporting window for "in the last N days" labels. */
function windowSpanLabel(t, windowDays) {
  const days = finiteValue(windowDays)
  if (days == null || days <= 0) return t('econSpanWindow')
  return t('econSpanDays', Math.max(1, Math.round(days)))
}

/** Monthly-equivalent fee lines, one per currency — never summed here. */
function econFeeLines(t, fees, groups = []) {
  const rows = Array.isArray(fees) ? fees : []
  if (!rows.length) return ['—']
  const completeness = new Map((groups || []).map(group => [group.currency, group.fee_complete !== false]))
  return rows.map(({ amount, currency }) => {
    const money = econMoneyValue(amount, currency, completeness.get(currency) !== false)
    return money !== '—' ? t('econPerMonth', money) : '—'
  })
}

const LEDGER_TABS = [['overview', 'Overview'], ['usage', 'Usage'], ['costs', 'Costs'],
  ['memberships', 'Memberships'], ['reports', 'Reports'], ['news', 'Model News'],
  ['settings', 'Settings']]
/** Tab ids to their I18N label keys. LEDGER_TABS keeps the canonical English labels. */
const TAB_LABEL_KEYS = {
  overview: 'tabOverview',
  usage: 'tabUsage',
  costs: 'tabCosts',
  memberships: 'tabMemberships',
  reports: 'tabReports',
  news: 'tabNews',
  settings: 'tabSettings',
}
const $digestDays = atom(30)
/** Model News view state: audience scope plus one category filter. */
const $newsScope = atom('foryou')
const $newsCategory = atom('all')
/** All Updates search text and observed-at window (null days = all time). */
const $newsSearch = atom('')
const $newsDays = atom(null)
/** How many All Updates entries are revealed before Load more (page size 10). */
const $newsShown = atom(10)
/** For You shows the first 5 groups until Show all is pressed; resets on scope change. */
const $newsShowAll = atom(false)
/** Ids of the open per-offer Details panels on news group cards. */
const $newsDetailsOpen = atom([])
/** Explicit refresh status: the Refresh button bypasses the local-diff throttle. */
const $newsRefreshState = atom(null)
/** Live-updates opt-in flow: confirm box plus the last notice, per connection. */
const $newsLiveState = atom(null)
/**
 * Set only by the tab bar's arrow/Home/End handler. LedgerPage replaces the
 * whole page (including this tab bar) on every tab change, so focusing the
 * outgoing tab loses focus to <body>; the newly mounted tab bar consumes
 * this flag and restores focus to its selected tab. Mouse and hash-driven
 * navigation never set it, so their focus behaviour is unchanged.
 */
let ledgerTabKeyboardNav = false
function LedgerTabs() {
  const t = usePluginI18n(ID)
  const tab = useValue($ledgerTab)
  useEffect(() => {
    if (typeof window === 'undefined' || typeof location === 'undefined') return undefined
    const sync = () => {
      const id = String(location.hash || '').replace('#', '')
      if (LEDGER_TABS.some(([known]) => known === id) && $ledgerTab.get() !== id) $ledgerTab.set(id)
    }
    window.addEventListener('hashchange', sync)
    return () => window.removeEventListener('hashchange', sync)
  }, [])
  useEffect(() => {
    if (!ledgerTabKeyboardNav) return
    ledgerTabKeyboardNav = false
    if (typeof document === 'undefined') return
    document.querySelector('.wm-product-tabs [role="tab"][aria-selected="true"]')?.focus()
  }, [tab])
  const onKeyDown = event => {
    if (!['ArrowRight', 'ArrowLeft', 'Home', 'End'].includes(event.key)) return
    const index = LEDGER_TABS.findIndex(([id]) => id === tab)
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? LEDGER_TABS.length - 1
      : (index + (event.key === 'ArrowRight' ? 1 : -1) + LEDGER_TABS.length) % LEDGER_TABS.length
    event.preventDefault()
    // No-op (Home on the first tab, End on the last): no page transition
    // will mount a new tab bar to consume the flag, so never set it — a
    // stale flag would restore focus after a later mouse navigation.
    if (LEDGER_TABS[next][0] === tab) return
    ledgerTabKeyboardNav = true
    goLedgerTab(LEDGER_TABS[next][0])
  }
  return jsxs('div', { className: 'wm-product-tabs', role: 'tablist', 'aria-label': t('tabListLabel'), onKeyDown, children: [
    jsxs('span', { className: 'wm-product-brand', children: [
      jsx('span', { className: 'wm-product-brand-mark', 'aria-hidden': true,
        children: jsx(BrandMark, { size: 20, id: 'tabs' }) }, 'mark'),
      jsxs('span', { className: 'wm-product-brand-copy', children: [
        jsx('strong', { children: 'SpendSense' }, 'name'),
        jsx('small', { children: 'by WolfMark' }, 'by')
      ] }, 'copy')
    ] }, 'brand'),
    ...LEDGER_TABS.map(([id]) =>
      jsx(ProductButton, { role: 'tab', variant: 'ghost', 'aria-label': t(TAB_LABEL_KEYS[id]),
        'aria-selected': tab === id, 'aria-pressed': tab === id, tabIndex: tab === id ? 0 : -1,
        className: cn('wm-product-tab', tab === id && 'wm-product-tab-active'), 'data-active': tab === id,
        onClick: () => { ledgerTabKeyboardNav = false; goLedgerTab(id) },
        children: jsx('span', { className: 'wm-product-tab-label', children: t(TAB_LABEL_KEYS[id]) }) }, id))
  ] })
}

function goLedgerTab(next) {
  $ledgerTab.set(next)
  try { if (typeof location !== 'undefined') history.replaceState(null, '', '#' + next) } catch {}
}

function profileDraft(profile, identity) {
    const [allowanceModel, modelAllowance] = Object.entries(profile.allowances || {})[0] || ['', '']
    return { ...profile, origin: identity,
      cycle_day: profile?.billing_cycle?.day || 1,
      rate_input: profile.rate_override?.input ?? '', rate_output: profile.rate_override?.output ?? '',
      rate_cache: profile.rate_override?.cache_read ?? '', allowance_model: allowanceModel,
      allowance_usd: allowanceModel ? modelAllowance : (profile.allowance_usd ?? ''),
      original_allowance_model: allowanceModel, original_scalar_allowance: profile.allowance_usd }
}

/* Budget guardrails share the account identity boundary and backend bridge. */
const $budgetDraft = atom(null)
const $budgetNotice = atom(null)
const $budgetBusy = atom(null)
let budgetActivityDirty = false
const BUDGET_RANK = { disabled: -2, unavailable: -1, normal: 0, info: 1, warning: 2, exceeded: 3 }
function budgetQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'budget-status', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('Budget service unavailable.')
      const result = await rest('/budgets/status')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (!result?.ok || !Array.isArray(result.budgets) || !Array.isArray(result.statuses)) throw new Error('Budget service unavailable.')
      return { ...result, identity }
    },
    retry: false, staleTime: 10_000, refetchInterval: 15_000
  }
}
function budgetLevel(value, budget, partial = false) {
  if (!budget?.enabled) return 'disabled'
  if (!Number.isFinite(value)) return 'unavailable'
  const pct = value / budget.amount * 100
  const thresholds = budget.thresholds || [50, 80, 100]
  if (pct >= thresholds[2]) return 'exceeded'
  if (pct >= thresholds[1]) return 'warning'
  if (pct >= thresholds[0]) return 'info'
  return partial ? 'unavailable' : 'normal'
}
function budgetColour(level) {
  return level === 'exceeded' ? 'var(--ui-error)' : level === 'warning' ? 'var(--ui-warning)' : undefined
}
function usageValueDelta(previous, delta, resolved, scope = membershipScopeNow(), evidence = {}) {
  // Version 1 lost call, tier and cache-price evidence. Its old monetary tally
  // cannot prove either coverage or a threshold; retain its tokens as unknown.
  const trusted = previous?.usageValueScope === scope && previous?.usageValueVersion === 2
  const oldTokens = previous ? tokensOf(previous) : 0
  const oldMissing = trusted ? Math.max(num(previous.usageValueMissing), oldTokens - num(previous.usageValuePriced)) : oldTokens
  const oldCalls = num(previous?.calls)
  const oldMissingCalls = trusted
    ? Math.max(num(previous.usageValueMissingCalls), oldCalls - num(previous.usageValueCallsTracked)) : oldCalls
  const exact = ['backend', 'live', 'remembered', 'bundled'].includes(resolved?.origin)
  const rates = resolved?.rates
  const known = value => typeof value === 'number' && Number.isFinite(value) && value >= 0
  const covered = !evidence.coalesced && rates?.usagePricingVersion === 2 && rates.usageTierKnown === true &&
    (!num(delta.input) || rates.usageInputKnown === true && known(rates.input)) &&
    (!num(delta.output) || rates.usageOutputKnown === true && known(rates.output)) &&
    (!num(delta.cacheRead) || rates.usageCacheKnown === true && known(rates.cache)) &&
    (!num(delta.cacheWrite) || rates.usageWriteKnown === true && known(rates.write))
  const priced = exact && covered ? costOf(delta, { input: rates.input ?? 0, output: rates.output ?? 0,
    cache: rates.cache ?? 0, write: rates.write ?? 0 }) : null
  const value = priced && Number.isFinite(priced.total) && priced.total >= 0 ? priced.total : null
  const missingCalls = evidence.missingCalls ?? (num(delta.calls) && !tokensOf(delta) ? num(delta.calls) : 0)
  return {
    usageValueVersion: 2, usageValueScope: scope,
    usageValueCost: (trusted ? num(previous.usageValueCost) : 0) + (value ?? 0),
    usageValuePriced: (trusted ? num(previous.usageValuePriced) : 0) + (value != null ? tokensOf(delta) : 0),
    usageValueMissing: num(oldMissing) + (value == null ? tokensOf(delta) : 0),
    usageValueCallsTracked: (trusted ? num(previous.usageValueCallsTracked) : 0) + num(delta.calls),
    usageValueMissingCalls: Math.max(0, oldMissingCalls + missingCalls - num(evidence.resolvedCalls))
  }
}

function sessionBudgetStatus(live, configured) {
  const limits = (configured || []).filter(b => b.enabled && b.scope === 'session' && b.measurement === 'api_equivalent' && b.currency === 'USD')
  const bucket = live.guardrailValue
  const trusted = bucket?.usageValueScope === membershipScopeNow() && bucket?.usageValueVersion === 2
  const cost = trusted && num(bucket.usageValuePriced) > 0 ? bucket.usageValueCost : null
  const partial = !trusted || num(bucket.usageValueMissing) > 0 || tokensOf(bucket) > num(bucket.usageValuePriced) ||
    num(bucket.usageValueMissingCalls) > 0 || num(bucket.calls) > num(bucket.usageValueCallsTracked)
  return limits.map(budget => ({ budget, spend: cost, partial,
    percentage: cost == null ? null : cost / budget.amount * 100,
    level: budgetLevel(cost, budget, partial) }))
    .sort((a, b) => BUDGET_RANK[b.level] - BUDGET_RANK[a.level] || (b.percentage || 0) - (a.percentage || 0))[0] || null
}
function budgetMetric(t, measurement) {
  return t(measurement === 'api_equivalent' ? 'budgetEstimated' : 'budgetActual')
}
function budgetTooltip(row, t) {
  const b = row.budget
  const amount = row.spend == null ? '—' : fmtMoney(row.spend, b.currency)
  const percent = row.percentage == null ? '—' : `${Math.round(row.percentage)}%`
  return `${b.label} · ${budgetMetric(t, b.measurement)} · ${amount}${row.partial || row.complete === false ? '+' : ''} / ${fmtMoney(b.amount, b.currency)} (${percent}) · ${t('budgetLevel_' + row.level)}`
}
function BudgetStatusIndicator({ data, error, t }) {
  if (!data?.budgets?.some(b => b.enabled && b.scope !== 'session')) return null
  const rows = data.statuses || []
  const highest = [...rows].filter(r => r.budget.enabled).sort((a, b) => BUDGET_RANK[b.level] - BUDGET_RANK[a.level])[0]
  const level = error ? 'unavailable' : highest?.level || 'unavailable'
  const tooltip = error ? t('budgetStale') : rows.filter(r => r.budget.enabled).map(r => budgetTooltip(r, t)).join('\n')
  return jsx('span', { className: 'tabular-nums', role: 'img', 'data-budget-monthly': level,
    style: { color: budgetColour(level) }, title: tooltip, 'aria-label': tooltip,
    children: `· ${level === 'exceeded' ? '■' : level === 'warning' ? '▲' : '◇'} ${t('budgetShort')}` })
}
async function budgetWrite(path, method, body, rev, identity, transport = rest) {
  if (!membershipIdentityCurrent(identity) || typeof transport !== 'function') throw new Error('Connection changed.')
  const result = await transport(`${path}?if_rev=${encodeURIComponent(rev)}`, { method, ...(body ? { body } : {}) })
  if (!result?.ok) throw new Error(result?.detail || result?.error || 'Budget save failed.')
  await queryClient.invalidateQueries({ queryKey: [ID, 'budget-status', identity] })
  return result
}
function budgetError(error, t) {
  const raw = String(error?.message || '')
  return /409|conflict/i.test(raw) ? t('budgetConflict') : /422|validation|threshold|amount|currency|timezone/i.test(raw) ? t('budgetInvalid') : t('budgetFailed')
}
function newBudgetDraft(identity, rev) {
  let zone = 'UTC'
  try { zone = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC' } catch {}
  return { origin: identity, rev, id: `budget-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    label: '', amount: '', currency: 'USD', scope: 'total', measurement: 'api_equivalent', provider: '', model: '',
    enabled: true, thresholds: [50, 80, 100], cycle_day: 1, timezone: zone }
}
function budgetPayload(draft) {
  const { origin, rev, ...body } = draft
  return { ...body, amount: Number(body.amount), cycle_day: Number(body.cycle_day),
    thresholds: body.thresholds.map(Number),
    provider: ['provider', 'model_route'].includes(body.scope) ? body.provider.trim() : '',
    model: body.scope === 'model_route' ? body.model.trim() : '', label: body.label.trim(),
    currency: body.scope === 'session' ? 'USD' : body.currency.toUpperCase(),
    measurement: body.scope === 'session' ? 'api_equivalent' : body.measurement }
}
function BudgetPanel({ manage = false, forecasts = false }) {
  const t = usePluginI18n(ID)
  const identity = useValue($membershipIdentity)
  const live = useLive()
  const query = useQuery(budgetQuery(identity))
  const rawDraft = useValue($budgetDraft)
  const busy = useValue($budgetBusy)
  const notice = useValue($budgetNotice)
  const current = query.data?.identity === identity && membershipIdentityCurrent(identity) ? query.data : null
  const draft = rawDraft?.origin === identity ? rawDraft : null
  const locked = busy?.origin === identity
  const set = (key, value) => $budgetDraft.set({ ...draft, [key]: value })
  const act = async (path, method, body, rev, clearDraft = false) => {
    if (locked || !membershipIdentityCurrent(identity)) return
    const token = { origin: identity }
    $budgetBusy.set(token)
    try {
      await budgetWrite(path, method, body, rev, identity)
      if (!membershipIdentityCurrent(identity)) return
      if (clearDraft && $budgetDraft.get() === draft) $budgetDraft.set(null)
      $budgetNotice.set({ origin: identity, text: t('budgetSaved') })
      await query.refetch?.()
    } catch (error) {
      if (membershipIdentityCurrent(identity)) $budgetNotice.set({ origin: identity, text: budgetError(error, t) })
    } finally { if ($budgetBusy.get() === token) $budgetBusy.set(null) }
  }
  const field = (key, label, type = 'text', choices = null) => jsxs('label', { className: 'wm-filter', children: [
    jsx('span', { children: t(label) }), choices
      ? jsx('select', { value: draft[key], disabled: locked, onChange: e => {
          if (key === 'scope' && e.target.value === 'session') $budgetDraft.set({ ...draft, scope: 'session', measurement: 'api_equivalent', currency: 'USD' })
          else set(key, e.target.value)
        }, children: choices.map(value => jsx('option', { value, children: t('budgetOption_' + value) }, value)) })
      : jsx('input', { value: draft[key], type, disabled: locked, required: true, step: type === 'number' ? 'any' : undefined,
          min: type === 'number' ? (key === 'cycle_day' ? 1 : .000001) : undefined, max: key === 'cycle_day' ? 31 : undefined,
          onChange: e => set(key, e.target.value) })
  ] }, key)
  const statusMap = new Map((current?.statuses || []).map(r => [r.id, r]))
  const allBudgets = current?.budgets || []
  const compact = !manage && !forecasts
  const list = compact ? [...allBudgets].sort((a, b) =>
    (BUDGET_RANK[statusMap.get(b.id)?.level] ?? -1) - (BUDGET_RANK[statusMap.get(a.id)?.level] ?? -1)).slice(0, 3) : allBudgets
  return jsxs('section', { className: 'wm-product-section wm-budgets', 'aria-label': t('budgetTitle'), children: [
    jsxs('div', { className: 'wm-budget-heading', children: [
      jsx('h2', { children: t('budgetTitle') }),
      jsx(InfoTip, { id: `budgets-${manage ? 'manage' : forecasts ? 'forecast' : 'overview'}`, label: t('infoLabel'), text: t('budgetHelp') }),
      manage ? jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: !current || locked || !!query.error,
        onClick: () => $budgetDraft.set(newBudgetDraft(identity, current.rev)), children: t('budgetAdd') }) : null
    ] }),
    query.error ? jsxs('p', { className: 'wm-warn-note', children: [t(current ? 'budgetStale' : 'budgetFailed'), ' ',
      jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => query.refetch?.(), children: t('budgetRetry') })] }) : null,
    !current && !query.error ? jsx('p', { children: t('budgetLoading') }) : null,
    current && !list.length ? jsxs('p', { children: [t('budgetEmpty'), ' ', !manage ? jsx('button', {
      type: 'button', className: 'wm-source-link', onClick: () => goLedgerTab('settings'), children: t('budgetManage') }) : null] }) : null,
    jsx('div', { className: 'wm-cost-list', children: list.map(budget => {
      const session = budget.scope === 'session' ? sessionBudgetStatus(live, [budget]) : null
      const row = session ? { ...session, complete: !session.partial, measurement: 'api_equivalent' } : statusMap.get(budget.id)
      const level = query.error ? 'unavailable' : row?.level || (budget.enabled ? 'unavailable' : 'disabled')
      const f = row?.forecast
      const alert = !query.error && row?.cycle && !row.dismissed && BUDGET_RANK[level] >= 1
      return jsxs('article', { className: 'wm-budget-row', 'data-budget-id': budget.id, children: [
        jsxs('div', { className: 'wm-budget-heading', children: [
          jsx('strong', { children: budget.label }),
          jsx('span', { className: 'wm-certainty', children: budgetMetric(t, budget.measurement) }),
          jsx('span', { style: { color: budgetColour(level) }, children: `${level === 'warning' ? '▲ ' : level === 'exceeded' ? '■ ' : ''}${t('budgetLevel_' + level)}` })
        ] }),
        jsx('small', { children: budget.scope === 'session' ? t('budgetSessionHelp') : `${t('budgetOption_' + budget.scope)}${budget.provider ? ' · ' + budget.provider : ''}${budget.model ? ' × ' + budget.model : ''} · ${budget.timezone} · ${row?.cycle?.start?.slice(0, 10) || '—'} → ${row?.cycle?.end?.slice(0, 10) || '—'}` }),
        jsx('div', { className: 'wm-budget-amount', title: row ? budgetTooltip(row, t) : t('budgetSessionHelp'), children:
          `${row?.spend == null ? '—' : fmtMoney(row.spend, budget.currency) + (row.complete ? '' : '+')} / ${fmtMoney(budget.amount, budget.currency)}${row?.percentage == null ? '' : ` · ${Math.round(row.percentage)}%`}` }),
        row ? jsx('progress', { max: 100, value: Math.max(0, Math.min(100, row.percentage || 0)), 'aria-label': budgetTooltip(row, t),
          style: { accentColor: budgetColour(level) || 'var(--ui-accent)' } }) : null,
        row?.coverage ? jsx('small', { children: t('budgetCoverage', row.coverage.calls, row.coverage.measured_calls,
          row.complete ? t('budgetComplete') : t('budgetPartial')) }) : null,
        forecasts && f ? jsx('p', { className: 'wm-budget-forecast', children: f.available
          ? t('budgetProjection', fmtMoney(f.projected, budget.currency), row.remaining == null ? '—' : fmtMoney(row.remaining, budget.currency),
              f.days_remaining == null ? '—' : String(f.days_remaining), f.breach_date || t('budgetNoBreach'))
          : t('budgetForecast_' + f.reason) }) : null,
        forecasts && f?.available ? jsx('small', { children: t('budgetBurn',
          f.burn_7 == null ? '—' : fmtMoney(f.burn_7, budget.currency), fmtMoney(f.burn_30, budget.currency),
          f.trend ? t('budgetTrend_' + f.trend) : '—', f.samples['30'].active_days, f.samples['30'].calls) }) : null,
        row?.fx ? jsx('small', { children: t('budgetFx', row.fx.usd_per_unit, row.fx.currency, row.fx.as_of, row.fx.source) }) : null,
        alert ? jsxs('div', { className: 'wm-budget-alert', role: 'status', children: [
          jsx('span', { children: budgetTooltip(row, t) }), jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: locked,
            onClick: () => act(`/budgets/${encodeURIComponent(budget.id)}/dismiss`, 'POST', { cycle: row.cycle.id, budget_rev: row.budget_rev, level }, current.rev), children: t('budgetDismiss') })
        ] }) : null,
        manage ? jsx('div', { className: 'wm-setting-action', children: [
          jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: locked || !!query.error,
            onClick: () => $budgetDraft.set({ ...budget, thresholds: [...budget.thresholds], origin: identity, rev: current.rev }), children: t('budgetEdit') }, 'edit'),
          jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: locked || !!query.error,
            onClick: () => act(`/budgets/${encodeURIComponent(budget.id)}`, 'DELETE', null, current.rev), children: t('budgetDelete') }, 'delete')
        ] }) : null
      ] }, budget.id)
    }) }),
    compact && allBudgets.length > 3 ? jsx('button', { type: 'button', className: 'wm-source-link', onClick: () => goLedgerTab('costs'), children: t('budgetViewAll', allBudgets.length) }) : null,
    manage && draft ? jsxs('form', { className: 'wm-custom-form', onSubmit: event => {
      event.preventDefault(); act(`/budgets/${encodeURIComponent(draft.id)}`, 'PUT', budgetPayload(draft), draft.rev, true)
    }, children: [
      jsx('div', { className: 'wm-custom-grid', children: [field('label', 'budgetName'), field('amount', 'budgetAmount', 'number'),
        field('scope', 'budgetScope', 'text', ['total', 'provider', 'model_route', 'session']),
        draft.scope !== 'session' ? field('measurement', 'budgetMeasurement', 'text', ['api_equivalent', 'actual_metered']) : null,
        draft.scope !== 'session' ? field('currency', 'budgetCurrency') : null,
        ['provider', 'model_route'].includes(draft.scope) ? field('provider', 'budgetProvider') : null,
        draft.scope === 'model_route' ? field('model', 'budgetModel') : null,
        draft.scope !== 'session' ? field('cycle_day', 'budgetCycleDay', 'number') : null,
        draft.scope !== 'session' ? field('timezone', 'budgetTimezone') : null
      ].filter(Boolean) }),
      jsx('div', { className: 'wm-custom-grid', children: [0, 1].map(index => jsxs('label', { className: 'wm-filter', children: [
        jsx('span', { children: t(index ? 'budgetWarningAt' : 'budgetInfoAt') }), jsx('input', { type: 'number', required: true, min: .001, max: 99.999, step: 'any', value: draft.thresholds[index], disabled: locked,
          onChange: event => set('thresholds', draft.thresholds.map((value, i) => i === index ? event.target.value : value)) })
      ] }, index)) }),
      jsxs('label', { className: 'wm-setting-toggle', children: [jsx('input', { type: 'checkbox', checked: draft.enabled, disabled: locked,
        onChange: event => set('enabled', event.target.checked) }), t('budgetEnabled')] }),
      jsx('small', { children: t('budgetThresholdHelp') }),
      jsx('div', { className: 'wm-setting-action', children: [
        jsx(ProductButton, { type: 'submit', className: 'wm-button', disabled: locked || !!query.error, children: t('budgetSave') }, 'save'),
        jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: locked, onClick: () => $budgetDraft.set(null), children: t('budgetCancel') }, 'cancel')
      ] })
    ] }) : null,
    notice?.origin === identity ? jsx('p', { role: 'status', children: notice.text }) : null
  ] })
}
const BUDGET_CSS = '.wm-budget-heading{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.wm-budget-heading h2{margin-right:auto}.wm-budget-row{padding:12px 0;border-top:1px solid var(--ui-stroke-secondary);min-width:0}.wm-budget-row:first-child{border-top:0}.wm-budget-row small{display:block;color:var(--ui-text-secondary);font-size:11.5px;line-height:1.5;overflow-wrap:anywhere}.wm-budget-amount{margin:7px 0;font-variant-numeric:tabular-nums;font-size:14px}.wm-budget-row progress{display:block;width:100%;height:6px;margin:8px 0}.wm-budget-alert{display:flex;align-items:center;gap:10px;justify-content:space-between;margin-top:8px;padding:8px;border:1px solid var(--ui-stroke-secondary);border-radius:6px;font-size:12px}.wm-budget-forecast{font-size:12px;line-height:1.5}.wm-budgets .wm-filter select{min-height:34px;max-width:100%;background:var(--ui-fill-primary);color:var(--ui-text-primary);border:1px solid var(--ui-stroke-secondary);border-radius:6px}.wm-budgets progress{appearance:auto}'

function AdvancedBillingRules() {
  const t = usePluginI18n(ID)
  const identity = useValue($membershipIdentity)
  const profilesQuery = useQuery(billingQuery(identity))
  const rawDraft = useValue($billingDraft)
  const notice = useValue($billingNotice)
  const draft = rawDraft?.origin === identity ? rawDraft : null
  const loaded = profilesQuery.data?.identity === identity && membershipIdentityCurrent(identity)
    ? profilesQuery.data.profiles || [] : []
  const advanced = loaded.filter(profile => !['subscription_included', 'subscription_credits', 'free'].includes(profile.kind))
  const legacy = loaded.length - advanced.length
  const errors = profileDraftErrors(draft, t)
  const startEdit = profile => $billingDraft.set(profileDraft(profile, identity))
  const update = (key, value) => $billingDraft.set({ ...draft, [key]: value })
  const save = async event => {
    event?.preventDefault?.()
    if (!draft || !membershipIdentityCurrent(draft.origin) || errors.length) return
    const captured = draft.origin
    try {
      await billingWrite('PUT', `/billing/profiles/${encodeURIComponent(draft.id)}`, profilePayload(draft))
      // Dependents are identity-scoped: the write landed, so they refresh even
      // when the draft moved on — or the connection switched — while it was
      // pending. The checks below protect UI updates only.
      await invalidateBillingDependentsFor(captured)
      if (!membershipIdentityCurrent(captured)) return
      if ($billingDraft.get() !== draft) return
      $billingNotice.set({ tone: 'good', origin: captured, text: t('advRulesSaved') })
      $billingDraft.set(null)
      await profilesQuery.refetch?.()
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $billingNotice.set({ tone: 'warn', origin: captured, text: billingErrorMessage(error, t) })
    }
  }
  const remove = async profile => {
    const captured = identity
    if (!membershipIdentityCurrent(captured)) return
    try {
      await billingWrite('DELETE', `/billing/profiles/${encodeURIComponent(profile.id)}`)
      // The write landed, so identity-scoped dependents refresh even when the
      // connection switched while it was pending; the check below guards UI only.
      await invalidateBillingDependentsFor(captured)
      if (!membershipIdentityCurrent(captured)) return
      $billingNotice.set({ tone: 'good', origin: captured, text: t('advRulesRemoved') })
      await profilesQuery.refetch?.()
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $billingNotice.set({ tone: 'warn', origin: captured, text: billingErrorMessage(error, t) })
    }
  }
  const field = (label, key, options = {}) => jsxs('label', { className: 'wm-filter', children: [
    jsx('span', { children: label }),
    options.choices
      ? jsx('select', { value: draft[key] ?? '', onChange: event => update(key, event.target.value),
        children: options.choices.map(([value, text]) => jsx('option', { value, children: text }, value)) })
      : jsx('input', { value: draft[key] ?? '', type: options.type || 'text', step: billingNumberStep(options), placeholder: options.placeholder || '',
        onChange: event => update(key, event.target.value) })
  ] }, key)
  return jsxs('section', { className: 'wm-product-section', children: keyedElementChildren([
    jsx('h2', { children: t('advRulesTitle') }),
    jsx('p', { children: t('advRulesIntro') }),
    legacy ? jsx('p', { className: 'wm-subtle', children: t('advRulesLegacy', legacy) }) : null,
    notice?.origin === identity ? jsx('div', { className: 'wm-alert', role: 'status', children: notice.text }) : null,
    profilesQuery.error ? jsx('div', { className: 'wm-alert', role: 'alert',
      children: String(profilesQuery.error.message || profilesQuery.error) }) : null,
    jsx('div', { className: 'wm-setting-action', children: [
      jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () =>
        $billingDraft.set({ id: '', kind: 'prepaid', provider: '', model: '', monthly_fee_usd: '',
          allowance_usd: '', allowance_model: '', cycle_day: 1, overage_paid: false,
          origin: identity }), children: t('advRulesAdd') }),
      jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => profilesQuery.refetch?.(),
        disabled: profilesQuery.isFetching, children: profilesQuery.isFetching ? t('advRulesRefreshing') : t('advRulesRefresh') })
    ] }),
    profilesQuery.isPending ? jsx('p', { className: 'wm-subtle', children: t('advRulesLoading') }) : null,
    advanced.length ? jsx('div', { className: 'wm-cost-list', children: advanced.map(profile => jsxs('div', {
      className: 'wm-cost-row', children: [
        jsxs('div', { children: [
          jsx('strong', { children: profile.label || profile.id }),
          jsx('small', { children: [profile.provider, profile.model, profile.kind].filter(Boolean).join(' · ') }),
          jsx('small', { children: profile.kind === 'custom' && profile.rate_override
            ? t('advRulesCustomRate', fmtUsd(profile.rate_override.input), fmtUsd(profile.rate_override.output))
            : profile.allowances ? Object.entries(profile.allowances).map(([model, value]) => t('advRulesModelAllowance', model, fmtUsd(value))).join(' · ')
              : profile.allowance_usd != null ? t('advRulesAllowance', fmtUsd(profile.allowance_usd)) : t('advRulesNoAllowance') })
        ] }),
        jsx('div', { className: 'wm-setting-action', children: [
          jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => startEdit(profile), children: t('advRulesEdit') }),
          jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => remove(profile), children: t('advRulesDelete') })
        ] })
      ]
    }, profile.id)) }) : !profilesQuery.isPending ? jsx('p', { className: 'wm-subtle', children: t('advRulesEmpty') }) : null,
    draft ? jsxs('form', { className: 'wm-custom-form', onSubmit: save, children: [
      jsx('h3', { children: draft.id ? t('advRulesEditTitle') : t('advRulesNewTitle') }),
      jsx('div', { className: 'wm-custom-grid', children: [
        field(t('advRulesFieldName'), 'id', { placeholder: t('advRulesPhName') }),
        field(t('advRulesFieldLabel'), 'label', { placeholder: t('advRulesPhOptional') }),
        field(t('advRulesFieldProvider'), 'provider', { placeholder: 'openai-codex' }),
        field(t('advRulesFieldModel'), 'model', { placeholder: 'provider/model' }),
        field(t('advRulesFieldKind'), 'kind', { choices: KIND_CHOICES.map(([value]) => [value, t(KIND_LABEL_KEYS[value])]) }),
        field(t('advRulesFieldAllowance'), 'allowance_usd', { type: 'number' }),
        field(t('advRulesFieldAllowanceModel'), 'allowance_model', { placeholder: 'provider/model' }),
        field(t('advRulesFieldCycleDay'), 'cycle_day', { type: 'number', step: '1' }),
        field(t('advRulesFieldFrom'), 'effective_from', { type: 'date' }),
        field(t('advRulesFieldTo'), 'effective_to', { type: 'date' }),
        field(t('advRulesFieldRateInput'), 'rate_input', { type: 'number' }),
        field(t('advRulesFieldRateOutput'), 'rate_output', { type: 'number' }),
        field(t('advRulesFieldRateCache'), 'rate_cache', { type: 'number' })
      ] }),
      jsx('p', { className: 'wm-subtle', children: t('advRulesEstimatesNote') }),
      jsx('div', { className: 'wm-setting-action', children: [
        jsx(ProductButton, { type: 'submit', className: 'wm-button', disabled: errors.length > 0, children: t('advRulesSave') }),
        jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => $billingDraft.set(null), children: t('advRulesCancel') })
      ] }),
      errors.length ? jsx('p', { className: 'wm-warn-note', role: 'alert', children: errors.join(' ') }) : null
    ] }) : null
  ], 'advanced-billing-rules') })
}

