const $settingsConfirmation = atom(null)
const $modelRefreshState = atom(null)
const $membershipClock = atom(Date.now())

function overviewAnalyticsQuery(identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'overview-analytics', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') throw new Error('Analytics is unavailable.')
      const result = await rest('/analytics?days=30')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (!result?.ok || !result.totals) throw new Error(result?.error || 'Analytics is unavailable.')
      return result
    },
    retry: false, staleTime: 30_000
  }
}

function settledDesktopMonth(ledger, now = new Date()) {
  const month = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`
  let cost = 0
  let priced = 0
  let unpriced = 0
  let unpricedCalls = 0
  let missingUsageCalls = 0
  let unknownCoverage = false
  for (const [day, buckets] of Object.entries(ledger?.days || {})) {
    if (!day.startsWith(month)) continue
    for (const bucket of Object.values(buckets || {})) {
      unknownCoverage ||= coverageUnknown(bucket)
      unpriced += Number(bucket?.unpricedTokens) || 0
      unpricedCalls += Number(bucket?.unpricedCalls) || 0
      missingUsageCalls += Number(bucket?.missingUsageCalls) || 0
      if (bucket?.legacy || !Number(bucket?.pricedTokens)) continue
      const value = Number(bucket?.cost)
      if (!Number.isFinite(value)) continue
      cost += value
      priced += Number(bucket.pricedTokens)
    }
  }
  return {
    known: priced > 0, cost, pricedTokens: priced, unpricedTokens: unpriced,
    unpricedCalls, missingUsageCalls, coverageUnknown: unknownCoverage
  }
}

function overviewTopModels(rows, limit = 4) {
  return (Array.isArray(rows) ? rows : [])
    .map(row => ({ ...row, calls: finiteValue(row?.calls) }))
    .filter(row => row.calls !== null && row.calls > 0)
    .sort((a, b) => b.calls - a.calls
      || String(a.provider || '').localeCompare(String(b.provider || ''))
      || String(a.model || '').localeCompare(String(b.model || '')))
    .slice(0, limit)
}

/** Fee bases contributing to the membership totals, so declared fees and
 * catalogue prices are never presented as one undifferentiated figure. */
function feeBasisMix(accounts) {
  const bases = new Set()
  for (const account of accounts || []) {
    const effective = account.fee?.effective
    if (effective && effective.amount !== null && effective.amount !== undefined) {
      bases.add(account.fee?.basis || 'unknown')
    }
  }
  return bases
}
function certaintyChip(certainty, text, key) {
  const tone = certainty === 'ok' ? 'positive' : certainty === 'estimated' ? 'action'
    : ['partial', 'lower-bound', 'unknown'].includes(certainty) ? 'attention'
      : certainty === 'declared' ? 'declared' : 'neutral'
  return jsx(StatusChip, { className: 'wm-certainty', 'data-certainty': certainty, tone, children: text }, key)
}
function OverviewPage() {
  const t = usePluginI18n(ID)
  const identity = useValue($membershipIdentity)
  const analytics = useQuery(overviewAnalyticsQuery(identity))
  const accounts = useQuery(membershipQuery(false, identity))
  useQuery(economicsQuery(identity))
  // Stored allowance readings only: native=false can never trigger a
  // provider request, so attention stays passive.
  const weather = useQuery(weatherQuery(identity, false))
  const ledger = useValue($ledger)
  const accountsReady = accounts.data?.identity === identity && membershipIdentityCurrent(identity)
  const currentAccounts = accountsReady
    ? membershipAccounts({ accounts: accounts.data.accounts }) : []
  const fees = membershipSummary(currentAccounts)
  const weatherCurrent = weather.data?.identity === identity && membershipIdentityCurrent(identity)
  const weatherById = new Map(
    ((weatherCurrent ? weather.data.accounts : []) || []).map(entry => [entry.account_id, entry]))
  // Retained verdicts after a failed refresh must not read as current —
  // same identity-guarded pattern as Memberships.
  const weatherStale = weatherById.size > 0 && !!(weather.error && membershipIdentityCurrent(identity))
  const local = settledDesktopMonth(ledger)
  const result = analytics.data?.totals || {}
  const unpricedTokens = Number(result.unpriced_tokens || 0)
  const unpricedCalls = Number(result.unpriced_calls || 0)
  const unpriced = unpricedTokens > 0 || unpricedCalls > 0
  const topModels = overviewTopModels(analytics.data?.by_model)
  const topModelMax = topModels[0]?.calls || 1
  // Accounts that could carry a recurring fee but have no known amount —
  // unpriced subscriptions, unconfirmed arrangements and plan-less
  // subscription accounts — are neither zero nor absent. Only api_only and
  // prepaid accounts are verified to have no recurring fee.
  const unknownFeeCount = currentAccounts.filter(account =>
    !['api_only', 'prepaid'].includes(account.effective_arrangement)
    && (account.fee?.effective?.amount === null || account.fee?.effective?.amount === undefined)).length
  const feeEntries = Object.keys(fees.byCurrencyPeriod || {}).length
  const items = accountsReady ? needsAttention(currentAccounts, weatherById, t) : []
  const bases = feeBasisMix(currentAccounts)
  const feeChips = ['declared', 'catalogue', 'custom']
    .filter(basis => bases.has(basis))
    .map(basis => certaintyChip(basis === 'declared' ? 'declared' : basis,
      basis === 'declared' ? t('ovCertDeclared') : basis === 'catalogue' ? t('ovCertCatalogue') : t('ovCertCustom'), basis))
  const scrollToAttention = () => {
    try {
      const reduce = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
      document.getElementById('wm-needs-attention')
        ?.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'start' })
    } catch {}
  }
  return jsx(ProductShell, { children:
    jsxs('main', { className: 'wm-shell', children: [
      jsx(ProductHeader, { title: t('ovTitle'), subtitle: t('ovSubtitle') }),
      analytics.error ? jsxs('div', { className: 'wm-alert', role: 'alert', children: [
        jsx('p', { children: t('ovBackendReadFailure') }),
        jsx(ProductButton, { type: 'button', disabled: analytics.isFetching,
          onClick: () => analytics.refetch?.(), children: t('econRetry') })
      ] }) : null,
      jsxs('section', { className: 'wm-product-summary wm-overview-grid', 'aria-label': t('ovFigures'), children: [
        jsxs(ProductCard, { as: 'article', className: 'wm-product-stat wm-kpi', 'data-kpi': 'recorded-usage', children: [
          jsx('div', { className: 'wm-kpi-eyebrow', children: t('ovRecordedLabel') }),
          jsx('div', { className: 'wm-kpi-figure', children: !local.known ? t('ovUnknown')
          : local.unpricedTokens || local.unpricedCalls || local.missingUsageCalls || local.coverageUnknown
            ? [jsx('small', { children: '≥' }, 'gte'), fmtUsd(local.cost), jsx('small', { children: ' ' + t('ovLowerBound') }, 'lb')]
            : fmtUsd(local.cost) }),
          jsx('p', { className: 'wm-kpi-prov', children: t('ovRecordedProv') }),
          local.coverageUnknown ? jsx('p', { className: 'wm-kpi-prov', children: t('ovCoverageUnknown') }) : null,
          jsxs('div', { className: 'wm-kpi-foot', children: [
            certaintyChip('estimated', t('ovCertRecorded'), 'recorded'),
            (local.unpricedTokens || local.unpricedCalls || local.missingUsageCalls || local.coverageUnknown) ? certaintyChip('partial', t('ovCertPartial'), 'rpart') : null
          ].filter(Boolean) })
        ] }),
        jsxs(ProductCard, { as: 'article', className: 'wm-product-stat wm-kpi', 'data-kpi': 'actual-charges', 'aria-label': t('ovChargesLabel'), children: [
          jsx('div', { className: 'wm-kpi-eyebrow', children: t('ovChargesLabel') }),
          jsx('div', { className: 'wm-kpi-figure', children: t('ovNotRecorded') }),
          jsx('p', { className: 'wm-kpi-prov', children: t('ovChargesEndpointProv') }),
          jsx('div', { className: 'wm-kpi-foot', children:
            certaintyChip('unknown', t('ovCertChargesUnknown'), 'charge-unknown') })
        ] }),
        jsxs(ProductCard, { as: 'article', className: 'wm-product-stat wm-kpi', 'data-kpi': 'api-equivalent-estimate', children: [
          jsx('div', { className: 'wm-kpi-eyebrow', children: t('ovEstimatedLabel') }),
          jsx('div', { className: 'wm-kpi-figure', children: result.list_usd == null ? t('ovUnknown')
            : unpriced ? [fmtUsd(result.list_usd), jsx('small', { children: ' ' + t('ovLowerBound') }, 'lb')] : fmtUsd(result.list_usd) }),
          jsx('p', { className: 'wm-kpi-prov', children: analytics.isLoading && !analytics.data ? t('ovBackendLoading')
            : analytics.error && !analytics.data ? t('ovBackendError')
            : !analytics.data ? t('ovBackendNone')
            : result.calls === 0 ? t('ovBackendEmpty') : unpricedCalls
              ? t('ovBackendUnpricedCalls', analyticsPricing(result, t)) : t('ovBackendProv') }),
          jsxs('div', { className: 'wm-kpi-foot', children: [
            certaintyChip('estimated', t('ovCertEstimated'), 'est'),
            unpriced ? certaintyChip('partial', t('ovCertPartial'), 'part') : null
          ].filter(Boolean) })
        ] }),
        jsxs(ProductCard, { as: 'article', className: 'wm-product-stat wm-kpi', 'data-kpi': 'saved-fees', children: [
          jsx('div', { className: 'wm-kpi-eyebrow', children: t('ovFeesLabel') }),
          jsx('div', { className: 'wm-kpi-figure', children: !accountsReady ? t('ovUnknown')
            : feeEntries ? feesLabel(fees, t)
            : unknownFeeCount ? t('ovUnknown') : t('ovNoFees') }),
          jsx('p', { className: 'wm-kpi-prov', children: !accountsReady
            ? accounts.error ? t('ovFeesError') : t('ovFeesLoading')
            : t('ovPlansConfirmed', fees.withPlan, fees.total) + '. ' + t('ovFeesSummaryProv')
              + (unknownFeeCount ? ' ' + t('ovFeesMissing', unknownFeeCount) : '') }),
          jsxs('div', { className: 'wm-kpi-foot', children: [
            ...feeChips,
            feeEntries && unknownFeeCount ? certaintyChip('partial', t('ovCertPartial'), 'fpart') : null,
            !feeEntries && unknownFeeCount ? certaintyChip('unknown', t('ovUnknown'), 'u') : null
          ].filter(Boolean) })
        ] })
      ] }),
      items.length || unpriced
        ? jsxs('div', { className: 'wm-attn-strip', role: 'region', 'aria-label': t('ovAttention'), children: [
            jsx('span', { className: 'wm-attn-dot', 'aria-hidden': true }),
            jsx('span', { children: t('ovStrip', items.length + (unpriced ? 1 : 0)) }),
            jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: scrollToAttention, children: t('ovStripReview') })
          ] })
        : null,
      jsxs('div', { className: 'wm-overview-panels', children: [
      jsxs(ProductCard, { as: 'section', className: 'wm-product-section wm-overview-attention', id: 'wm-needs-attention', 'aria-label': items.length || unpriced ? t('ovAttention') : t('ovContinue'), children: [
        jsx('h2', { children: items.length || unpriced ? t('ovAttention') : t('ovContinue') }),
        items.length || unpriced
          ? jsx('p', { children: t('ovAttentionHint') })
          : jsx('p', { children: t('ovNothingToDo') }),
        weatherStale ? jsx('p', { className: 'wm-subtle', role: 'status', children: t('ovWeatherStale') }) : null,
        items.length || unpriced
          ? jsxs('ul', { className: 'wm-attention-rows', children: [
              ...items.slice(0, 3).map((item, index) => jsxs('li', { children: [
                jsx('span', { className: 'wm-attn-dot', 'data-tone': item.tone === 'warn' ? 'warn' : 'info', 'aria-hidden': true }),
                jsxs('div', { className: 'wm-attn-main', children: [
                  jsx('strong', { children: item.account.label || item.account.family }),
                  jsx('span', { children: item.text })
                ] }),
                jsx(ProductButton, { type: 'button', className: 'wm-button',
                  onClick: () => { queueMembershipTarget(item); goLedgerTab('memberships') },
                  children: attentionActionLabel(item.issue, t) })
              ] }, index)),
              unpriced ? jsxs('li', { children: [
                jsx('span', { className: 'wm-attn-dot', 'data-tone': 'info', 'aria-hidden': true }),
                jsxs('div', { className: 'wm-attn-main', children: [
                  jsx('strong', { children: t('ovPricingTitle') }),
                  jsx('span', { children: t('ovUnpriced', unpricedTokens, unpricedCalls) })
                ] }),
                jsx(ProductButton, { type: 'button', className: 'wm-button',
                  onClick: () => goLedgerTab('usage'), children: t('ovOpenUsage') })
              ] }, 'unpriced') : null
            ].filter(Boolean) })
          : null,
        jsx('div', { className: 'wm-setting-action', children: [
          items.length ? jsx(ProductButton, { type: 'button', className: 'wm-button wm-accent', onClick: () => goLedgerTab('memberships'), children: t('ovReviewMemberships') }) : null,
          jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => goLedgerTab('usage'), children: t('ovOpenUsage') }),
          jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => goLedgerTab('costs'), children: t('ovOpenCosts') }),
          items.length ? null : jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => goLedgerTab('memberships'), children: t('ovManageMemberships') })
        ].filter(Boolean) })
      ] }),
      jsxs(ProductCard, { as: 'section', className: 'wm-product-section wm-overview-models', 'aria-label': t('ovModelsTitle'), children: [
        jsx('h2', { children: t('ovModelsTitle') }),
        jsx('p', { children: t('ovModelsSubtitle') }),
        !analytics.data && analytics.isLoading
          ? jsx('p', { role: 'status', children: t('ovModelsLoading') })
          : !analytics.data && analytics.error
            ? jsx('p', { role: 'status', children: t('ovModelsUnavailable') })
            : topModels.length
              ? jsx('ol', { className: 'wm-overview-model-list', children: topModels.map((row, index) => {
                  const model = typeof row.model === 'string' && row.model.trim() ? row.model : t('unknown')
                  const provider = typeof row.provider === 'string' && row.provider.trim() ? row.provider : t('unknown')
                  const ratio = Math.max(0, Math.min(100, Math.round((row.calls / topModelMax) * 100)))
                  return jsxs('li', { className: 'wm-overview-model-row', children: [
                    jsxs('div', { className: 'wm-overview-model-head', children: [
                      jsxs('span', { className: 'wm-overview-model-name', children: [
                        jsx('strong', { children: model }), jsx('small', { children: provider })
                      ] }),
                      jsx('strong', { className: 'wm-overview-model-count', children: t('ovModelCalls', row.calls) })
                    ] }),
                    jsx('span', { className: 'wm-overview-model-track', 'aria-hidden': true, children:
                      jsx('span', { className: 'wm-overview-model-fill', style: { width: `${ratio}%` } }) })
                  ] }, `${provider}/${model}`)
                }) })
              : result.calls === 0 ? jsx('p', { children: t('ovModelsEmpty') })
                : jsx('p', { children: t('ovModelsBreakdownUnavailable') }),
        jsx('div', { className: 'wm-setting-action', children:
          jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => goLedgerTab('usage'), children: t('ovOpenUsage') }) })
      ] })
      ] }),
      jsx(BudgetPanel, {}),
      jsxs('details', { className: 'wm-method', children: [
        jsx('summary', { children: t('ovMethodTitle') }),
        jsx('div', { children: jsx('p', { children: t('ovMethodBody') }) })
      ] })
    ] })
  })
}

/** In-page jump that never touches the host hash (hash changes corrupt returnTo). */
function jumpToSettingsSection(id) {
  try {
    if (typeof document === 'undefined') return
    const reduce = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
    const target = document.getElementById(id)
    target?.scrollIntoView?.({ behavior: reduce ? 'auto' : 'smooth', block: 'start' })
    // Land keyboard and screen-reader users on the destination heading.
    const heading = target?.querySelector('h2') || target
    if (heading && !heading.hasAttribute('tabindex')) heading.setAttribute('tabindex', '-1')
    try { heading?.focus({ preventScroll: true }) } catch {
      try { heading?.focus() } catch {}
    }
  } catch {}
}
function SettingsPage() {
  const t = usePluginI18n(ID)
  const identity = useValue($membershipIdentity)
  const status = useQuery(pricingStatusQuery(identity))
  const planCatalogue = useQuery(membershipPlansQuery(identity))
  const health = useQuery({
    queryKey: [ID, 'health', identity],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      const result = await rest('/health')
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (!result?.ok) throw new Error(result?.error || 'Health check failed.')
      return result
    },
    retry: false, staleTime: 30_000
  })
  const confirmation = useValue($settingsConfirmation)
  const refreshState = useValue($modelRefreshState)
  const automaticModelOptions = useValue($automaticModelOptions)
  const liveConfirmation = confirmation?.origin === identity ? confirmation : null
  const liveRefresh = refreshState?.origin === identity ? refreshState : null
  const [clock] = [useValue($membershipClock)]
  const newsSettings = useQuery(newsSettingsQuery(identity))
  const liveNewsState = useValue($newsLiveState)
  const liveNewsView = liveNewsState?.origin === identity ? liveNewsState : null
  const liveNewsKnown = newsSettings.data?.identity === identity && membershipIdentityCurrent(identity)
  const liveNewsOn = liveNewsKnown ? !!newsSettings.data.settings?.live_updates : null

  const saveLiveNews = async next => {
    const captured = identity
    try {
      const result = await newsSaveSettings(next)
      if (!membershipIdentityCurrent(captured)) return
      $newsLiveState.set({ origin: captured, tone: 'good',
        text: t('newsLiveSaved', !!result?.live_updates) })
      await invalidateNewsFor(captured)
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $newsLiveState.set({ origin: captured,
        tone: 'warn', text: t('newsLiveFailed') + ' ' + String(error.message || error) })
    }
  }

  const copyRecovery = async () => {
    const captured = identity
    if (!membershipIdentityCurrent(captured)) return
    try {
      const [accountDoc, profileDoc, budgetDoc] = await Promise.all([
        rest('/membership/accounts'), rest('/billing/profiles'), rest('/budgets')
      ])
      if (!membershipIdentityCurrent(captured)) return
      if (!Array.isArray(accountDoc?.accounts) || accountDoc?.store?.error || !accountDoc?.seat_store || !accountDoc?.entitlement_store || !accountDoc?.membership_store ||
          !Array.isArray(profileDoc?.profiles) || profileDoc?.error || !Array.isArray(budgetDoc?.budgets) || !budgetDoc.rev) {
        throw new Error('The user-data export is incomplete.')
      }
      const bundle = {
        product: 'Spend Sense',
        version: PLUGIN_VERSION,
        exported_at: new Date().toISOString(),
        note: 'This contains Spend Sense membership, seat history, route entitlement relationships, budget and advanced-rule data. It contains no provider credential secrets or recorded usage ledger.',
        memberships: accountDoc.accounts,
        membership_store: accountDoc.membership_store,
        seat_history: accountDoc.seat_store,
        route_entitlements: accountDoc.entitlement_store,
        advanced_rules: profileDoc.profiles,
        budget_guardrails: budgetDoc
      }
      const copied = await writeClipboard(JSON.stringify(bundle, null, 2))
      if (!membershipIdentityCurrent(captured)) return
      if (!copied) throw new Error('Clipboard access was unavailable.')
      $settingsConfirmation.set({ origin: captured, stage: 'data-copied' })
    } catch (error) {
      if (membershipIdentityCurrent(captured)) {
        $modelRefreshState.set({ origin: captured, tone: 'warn',
          text: String(error.message || error) })
      }
    }
  }

  const resetPreferences = () => {
    if (!liveConfirmation || liveConfirmation.stage !== 'reset-preferences' ||
        !membershipIdentityCurrent(identity)) {
      $settingsConfirmation.set({ origin: identity, stage: 'reset-preferences' })
      return
    }
    try {
      for (const key of ['range', 'view', 'group', 'basis', 'automatic-model-options']) storage?.delete?.(key)
      $range.set('today')
      $view.set(VIEW_ALL)
      $group.set('route')
      $basis.set('hybrid')
      $automaticModelOptions.set(false)
      $settingsConfirmation.set(null)
      $modelRefreshState.set({ origin: identity, tone: 'good', text: t('settingsNotifyPrefsReset') })
    } catch (error) {
      $modelRefreshState.set({ origin: identity, tone: 'warn', text: t('settingsNotifyPrefsFailed', String(error.message || error)) })
    }
  }

  const resetUserData = async () => {
    if (!liveConfirmation || liveConfirmation.stage !== 'data-copied' ||
        !membershipIdentityCurrent(identity)) return
    const captured = identity
    try {
      const result = await rest('/settings/reset-user-data', {
        method: 'POST', body: { confirm: 'RESET_USER_ENTERED_DATA' }
      })
      if (!membershipIdentityCurrent(captured) || !result?.ok) return
      $settingsConfirmation.set(null)
      $membershipSnapshot.set({ identity: captured, accounts: [], store: { loaded: true, error: '' }, notes: [] })
      await queryClient.invalidateQueries({ queryKey: [ID, 'membership-accounts', captured] })
      await queryClient.invalidateQueries({ queryKey: [ID, 'billing-profiles', captured] })
      await queryClient.invalidateQueries({ queryKey: [ID, 'budget-status', captured] })
      $budgetDraft.set(null)
      $budgetNotice.set(null)
      await invalidateEconomicsFor(captured)
      await invalidateWeatherFor(captured)
      $modelRefreshState.set({ origin: captured, tone: 'good', text: t('settingsNotifyDataCleared') })
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $modelRefreshState.set({
        origin: captured, tone: 'warn', text: t('settingsNotifyDataFailed', String(error.message || error))
      })
    }
  }

  const refreshModels = async () => {
    if (!liveRefresh || !membershipIdentityCurrent(identity)) {
      $modelRefreshState.set({ origin: identity, stage: 'confirm-models' })
      return
    }
    const captured = identity
    try {
      const sessionId = host.state.focusedSessionId?.get?.() || null
      const model = host.state.model?.get?.() || ''
      const params = { refresh: true, ...(sessionId ? { session_id: sessionId } : {}) }
      const result = await host.request('model.options', params)
      if (!membershipIdentityCurrent(captured)) return
      const query = catalogQuery(sessionId, model)
      queryClient.setQueryData(query.queryKey, result)
      if (!sessionId) queryClient.setQueryData(catalogQuery(null).queryKey, result)
      $modelRefreshState.set({ origin: captured, tone: 'good', text: t('settingsNotifyModelsOk') })
      $settingsConfirmation.set(null)
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $modelRefreshState.set({ origin: captured, tone: 'warn',
        text: t('settingsNotifyModelsFailed', String(error.message || error)) })
    }
  }

  const refreshPlansCatalogue = async () => {
    const captured = identity
    try {
      const result = await rest('/membership/plans/refresh', { method: 'POST' })
      if (!membershipIdentityCurrent(captured)) return
      if (!result || result.ok === false) throw new Error(result?.error || 'The plan catalogue is unavailable.')
      queryClient.setQueryData([ID, 'membership-plans', captured], { ...result, identity: captured })
      const centralState = result?.central?.state
      const centralAlert = newsCentralAlert(result?.central, t)
      if (centralState === 'ok') $modelRefreshState.set({ origin: captured, tone: 'good', text: t('settingsNotifyCatalogueOk') })
      else if (centralAlert) $modelRefreshState.set({ origin: captured, tone: 'warn',
        text: t('settingsNotifyCatalogueFailed', centralAlert) })
      else $modelRefreshState.set({ origin: captured, tone: 'warn', text: t('settingsNotifyLiveOff') })
    } catch (error) {
      if (membershipIdentityCurrent(captured)) $modelRefreshState.set({ origin: captured, tone: 'warn',
        text: t('settingsNotifyCatalogueFailed', String(error.message || error)) })
    }
  }

  const pricing = status.data
  const membershipBook = planCatalogue.data?.identity === identity && membershipIdentityCurrent(identity)
    ? planCatalogue.data : null
  const last = health.data
  return jsx(ProductShell, { children:
    jsxs('main', { className: 'wm-shell', children: [
      jsx(ProductHeader, { title: t('settingsTitle'),
        subtitle: t('settingsSubtitle') }),
      jsx('nav', { className: 'wm-account-jump', 'aria-label': t('settingsNavLabel'), children: [
        ['settings-budgets', 'budgetTitle'],
        ['settings-pricing', 'settingsPricingHeading'],
        ['settings-live', 'newsLiveTitle'],
        ['settings-models', 'settingsModelsHeading'],
        ['settings-billing', 'advRulesTitle'],
        ['settings-data', 'settingsRecoveryHeading'],
        ['settings-diagnostics', 'settingsDiagnosticsHeading'],
        ['settings-about', 'settingsAboutHeading'],
      ].map(([id, key]) => jsx('button', { type: 'button', className: 'wm-account-chip',
        onClick: () => jumpToSettingsSection(id), children: t(key) }, id)) }),
      jsxs('div', { className: 'wm-settings-grid', children: keyedElementChildren([
        jsx('div', { id: 'settings-budgets', children: jsx(BudgetPanel, { manage: true }) }),
        jsxs('section', { id: 'settings-pricing', className: 'wm-product-section', children: [
          jsx('h2', { children: t('settingsPricingHeading') }),
          jsx('p', { children: t('settingsPrivacyP1') }),
          status.error ? jsx('p', { className: 'wm-warn-note', children: t('settingsPricingUnavailable') }) : null,
          pricing ? jsxs('p', { children: [
            t('settingsPricingSourceLabel'), jsx('strong', { children: pricing.source || t('settingsPricingNoSource') }),
            pricing.as_of ? t('settingsPricingDate', new Date(pricing.as_of).toLocaleString()) : t('settingsPricingNoDate'),
            pricing.age_seconds != null ? t('settingsPricingAge', Math.round(pricing.age_seconds / 3600)) : '',
            pricing.stale ? t('settingsPricingStale') : ''
          ] }) : null,
          jsx('p', { className: 'wm-subtle', children: t('settingsPricingRefreshNote') }),
          jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: status.isFetching,
            onClick: () => status.refetch?.(), children: status.isFetching ? t('settingsChecking') : t('settingsRefreshPricing') }),
          jsxs('p', { children: [
            t('settingsCapturedCosts')
          ] }),
          jsx('p', { children: t('settingsCatalogueFeed') }),
          membershipBook ? jsxs('div', { className: 'wm-note', children: [
            jsx('p', { children: t('settingsCatalogueVersion',
              membershipBook.source === 'live' ? t('settingsCatalogueLive') : t('settingsCatalogueBundled'),
              membershipBook.catalogue_version,
              membershipBook.generated_at ? t('settingsCatalogueGenerated', new Date(membershipBook.generated_at).toLocaleString()) : '') }),
            membershipBook.source === 'live' && membershipBook.central
              ? jsx('p', { className: 'wm-subtle', children: t('settingsCatalogueFetched',
                  newsFreshLabel(newsAgeDays(membershipBook.central.fetched_at, Date.now()), t),
                  membershipBook.central.fetched_at ? t('settingsCatalogueFetchedAt', new Date(membershipBook.central.fetched_at).toLocaleString()) : '') })
              : null,
            newsCentralAlert(membershipBook.central, t)
              ? jsx('p', { className: 'wm-warn-note', role: 'status', children: t('settingsCentralAlert',
                  newsCentralAlert(membershipBook.central, t), membershipBook.source === 'live') })
              : null,
            membershipBook.source === 'bundled' && membershipBook.central?.held_back
              ? jsx('p', { className: 'wm-warn-note', role: 'status', children: t('settingsCentralHeldBack',
                  membershipBook.central.catalogue_version || t('settingsCentralUpdate')) })
              : null,
            jsx('p', { children: t('settingsCatalogueTotals', membershipBook.totals?.plans || 0,
              membershipBook.totals?.verified || 0, membershipBook.totals?.provisional || 0,
              membershipBook.totals?.placeholders || 0) }),
            jsx(ProductButton, { type: 'button', className: 'wm-button', disabled: planCatalogue.isFetching,
              onClick: refreshPlansCatalogue, children: planCatalogue.isFetching ? t('settingsChecking') : t('settingsRefreshCatalogue') }),
            jsx('details', { children: [
              jsx('summary', { children: t('settingsSourceRegister',
                membershipBook.source === 'live' ? t('settingsCatalogueLive') : t('settingsCatalogueBundled')) }),
              jsx('ul', { children: (membershipBook.sources || []).map(source => jsx('li', { children: [
                source.id + ' · ' + source.evidence_kind + ' · ' + (source.retrieved_at || t('settingsSourceNoDate')) + ' · ',
                jsx('a', { href: source.url, target: '_blank', rel: 'noreferrer', children: source.url })
              ] }, source.id)) })
            ] })
          ] }) : planCatalogue.error ? jsx('p', { className: 'wm-warn-note', children: t('settingsCatalogueProvenanceUnavailable') }) : null
        ] }),
        jsxs('section', { id: 'settings-live', className: 'wm-product-section', children: [
          jsx('h2', { children: t('newsLiveTitle') }),
          jsx('p', { children: t('newsLiveExplain') }),
          jsx('p', { children: t('newsLiveIp') }),
          newsSettings.error && membershipIdentityCurrent(identity)
            ? jsx('p', { className: 'wm-warn-note', role: 'status', children: t('newsLiveFailed') }) : null,
          jsx('label', { className: 'wm-setting-toggle', children: [
            jsx('input', { type: 'checkbox', checked: liveNewsOn === true, disabled: liveNewsOn == null,
              onChange: event => {
                if (!membershipIdentityCurrent(identity)) return
                if (event.target.checked) $newsLiveState.set({ origin: identity, stage: 'confirm-live' })
                else saveLiveNews(false)
              } }),
            jsx('span', { children: t('newsLiveToggle') }),
          ] }),
          liveNewsView?.stage === 'confirm-live'
            ? jsx('div', { className: 'wm-confirm-box', children: [
                jsx('p', { role: 'alert', children: t('newsLiveConfirmText') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button',
                  onClick: () => saveLiveNews(true), children: t('newsLiveConfirm') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button',
                  onClick: () => $newsLiveState.set(null), children: t('newsLiveCancel') }),
              ] })
            : null,
          liveNewsView?.text
            ? jsx('p', { className: liveNewsView.tone === 'warn' ? 'wm-warn-note' : 'wm-subtle',
                role: 'status', children: liveNewsView.text })
            : null,
          liveNewsOn === true ? jsx('p', { className: 'wm-subtle', children: t('newsLiveOn') })
            : liveNewsOn === false ? jsx('p', { className: 'wm-subtle', children: t('newsLiveOff') })
              : null,
        ] }),
        jsxs('section', { id: 'settings-models', className: 'wm-product-section', children: [
          jsx('h2', { children: t('settingsModelsHeading') }),
          jsx('p', { children: t('settingsModelsExplain') }),
          jsx('p', { children: t('settingsPrivacyP2') }),
          jsx('label', { className: 'wm-setting-toggle', children: [
            jsx('input', { type: 'checkbox', checked: automaticModelOptions,
              onChange: event => $automaticModelOptions.set(Boolean(event.target.checked)) }),
            jsx('span', { children: t('settingsAutoRefreshToggle') })
          ] }),
          jsx('p', { children: t('settingsPrivacyP4') }),
          liveRefresh?.stage === 'confirm-models'
            ? jsx('div', { className: 'wm-confirm-box', children: [
                jsx('p', { role: 'alert', children: t('settingsModelsConfirmText') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: refreshModels, children: t('settingsModelsConfirm') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => $modelRefreshState.set(null), children: t('settingsCancel') })
              ] })
            : jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: refreshModels, children: t('settingsRefreshModels') }),
          liveRefresh?.text ? jsx('p', { className: liveRefresh.tone === 'warn' ? 'wm-warn-note' : 'wm-subtle',
            role: 'status', children: liveRefresh.text }) : null
        ] }),
        jsx('div', { id: 'settings-billing', children: jsx(AdvancedBillingRules, {}) }),
        jsxs('section', { id: 'settings-data', className: 'wm-product-section', children: [
          jsx('h2', { children: t('settingsRecoveryHeading') }),
          jsx('p', { children: t('settingsRecoveryPrefsExplain') }),
          liveConfirmation?.stage === 'reset-preferences'
            ? jsx('div', { className: 'wm-confirm-box', children: [
                jsx('p', { role: 'alert', children: t('settingsRecoveryPrefsConfirmText') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: resetPreferences, children: t('settingsRecoveryPrefsConfirm') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => $settingsConfirmation.set(null), children: t('settingsCancel') })
              ] })
            : jsx(ProductButton, { type: 'button', className: 'wm-button',
                onClick: () => $settingsConfirmation.set({ origin: identity, stage: 'reset-preferences' }),
                children: t('settingsResetPrefs') }),
          jsx('p', { children: t('settingsRecoveryDataExplain') }),
          jsx('p', { children: t('settingsPrivacyP3') }),
          liveConfirmation?.stage === 'data-copied'
            ? jsx('div', { className: 'wm-confirm-box', children: [
                jsx('p', { role: 'alert', children: t('settingsRecoveryBackupText') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: resetUserData, children: t('settingsRecoveryDataConfirm') }),
                jsx(ProductButton, { type: 'button', className: 'wm-button', onClick: () => $settingsConfirmation.set(null), children: t('settingsCancel') })
              ] })
            : jsx(ProductButton, { type: 'button', className: 'wm-button',
                onClick: copyRecovery, children: t('settingsCopyBackup') })
        ] }),
        jsxs('section', { id: 'settings-diagnostics', className: 'wm-product-section', children: [
          jsx('h2', { children: t('settingsDiagnosticsHeading') }),
          jsx('p', { children: t('settingsDiagnosticsVersions', PLUGIN_VERSION,
            last?.version ? t('settingsDiagnosticsBackend', last.version)
              : health.isPending ? t('settingsDiagnosticsChecking') : t('settingsDiagnosticsNoBackend')) }),
          health.error ? jsx('p', { className: 'wm-warn-note', role: 'status',
            children: t('settingsHealthFailed', String(health.error.message || health.error)) }) : null,
          last ? jsx('p', { children: last.ok ? t('settingsHealthReady') : t('settingsHealthUnavailable') }) : null,
          jsx('details', { className: 'wm-note', children: [
            jsx('summary', { children: t('settingsDiagnosticsRecent') }),
            membershipDiagnostics.length
              ? jsx('ul', { children: membershipDiagnostics.map((entry, index) => jsx('li', {
                  children: `${entry.at} · ${entry.method} ${entry.path} · ${entry.status ?? entry.outcome} · ${entry.scope}`
                }, index)) })
              : jsx('p', { children: t('settingsDiagnosticsEmpty') })
          ] }),
          jsx('p', { className: 'wm-subtle', children: t('settingsDiagnosticsNote') })
        ] }),
        jsxs('section', { id: 'settings-about', className: 'wm-product-section', children: [
          jsx('h2', { children: t('settingsAboutHeading') }),
          jsx(BrandMark, { size: 32, id: 'about' }),
          jsx('p', { children: t('settingsAboutVersion', PLUGIN_VERSION) }),
          jsx('p', { children: t('settingsAboutCredit') }),
          jsx('p', { children: t('settingsAboutSupport') }),
          jsx('ul', { style: { listStyle: 'none', margin: '8px 0 12px', padding: 0, display: 'grid', gap: '6px' }, children: [
            ['https://wolfmark.co.uk/', 'settingsLinkWolfmark'],
            ['https://github.com/WolfMark-Ltd/spendsense', 'settingsLinkRepo'],
            ['https://github.com/WolfMark-Ltd/spendsense/issues/new?template=bug-report.yml', 'settingsLinkBug'],
            ['https://github.com/WolfMark-Ltd/spendsense/issues/new?template=feature-request.yml', 'settingsLinkFeature'],
            ['https://github.com/WolfMark-Ltd/spendsense/blob/main/docs/quickstart.md', 'settingsLinkDocs'],
            ['https://wolfmark.co.uk/contact', 'settingsAboutContact'],
          ].map(([href, key]) => jsx('li', { children: jsx('a', { href, target: '_blank', rel: 'noreferrer',
            className: 'wm-source-link', children: t(key) }) }, key)) }),
          jsxs('details', { children: [
            jsx('summary', { children: t('settingsAboutLicenceHeading') }),
            jsx('p', { children: t('settingsAboutLicenceText') }),
          ] }),
          jsx('p', { className: 'wm-subtle', children: t('settingsAboutCatalogueNote') })
        ] })
      ], 'settings-grid') }),
      liveRefresh?.tone === 'warn' && !liveRefresh.stage
        ? jsx('div', { className: 'wm-alert', role: 'status', children: liveRefresh.text }) : null,
          jsx('p', { className: 'wm-subtle', children: t('settingsPanePlacement') })
    ] })
  })
}

/* --------------------------------------------------------- all hermes view */

/** Backend query for the authoritative ledger. `rest` is ctx.rest (scoped). */
function backendQuery(days, basis, identity = membershipIdentityNow()) {
  return {
    queryKey: [ID, 'ledger', identity, days, basis],
    queryFn: async () => {
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      if (typeof rest !== 'function') {
        throw new Error('This desktop build has no plugin backend bridge (ctx.rest).')
      }
      const result = await rest(`/ledger?days=${days}&basis=${encodeURIComponent(basis)}`)
      if (!membershipIdentityCurrent(identity)) throw new Error('Connection changed.')
      return { ...result, identity }
    },
    retry: false,
    staleTime: 30_000
  }
}

function ViewToggle({ t, view }) {
  return jsx(SegmentedControl, {
    onChange: v => $view.set(v),
    options: [
      { id: VIEW_ALL, label: t('viewAll') },
      { id: VIEW_DESKTOP, label: t('viewDesktop') }
    ],
    value: view
  })
}

function RangeToggle({ t, range }) {
  return jsx(SegmentedControl, {
    onChange: v => $range.set(v),
    options: ['today', 'week', 'month', 'all'].map(id => ({ id, label: t(`range_${id}`) })),
    value: range
  })
}

function BasisToggle({ t, basis }) {
  return jsx(SegmentedControl, {
    onChange: v => $basis.set(v),
    options: ['hybrid', 'billed', 'list'].map(id => ({ id, label: t(`basis_${id}`) })),
    value: basis
  })
}

function CloseButton({ t }) {
  return jsx(Tip, {
    label: t('closeTip'),
    children: jsx(Button, {
      'aria-label': t('close'),
      onClick: closeLedger,
      size: 'icon-sm',
      variant: 'ghost',
      children: jsx(Codicon, { name: 'close' })
    })
  })
}

function Stat({ hint, label, value, warn }) {
  return jsxs('div', {
    className: 'rounded-md border border-(--ui-stroke-secondary) p-3',
    children: [
      jsx('div', { className: 'text-[0.6875rem] text-(--ui-text-quaternary)', children: label }),
      jsx('div', {
        className: cn('text-lg font-semibold tabular-nums', warn ? 'text-(--ui-warning)' : ''),
        children: value
      }),
      hint ? jsx('div', { className: 'text-[0.625rem] text-(--ui-text-quaternary)', children: hint }) : null
    ].filter(Boolean)
  })
}

function GroupTable({ group, rows, t }) {
  const head = [t('groupName'), t('tokens'), t('calls'), t('billed'), t('list'), t('basis'), t('status')]
  const cells = row => {
    const subtitle =
      group === 'model' ? row.provider : group === 'route' ? `${row.models ? row.models.length : 0} ${t('models')}` : ''
    const list = row.list_usd == null
      ? t('unpriced')
      : `${row.list_usd_upper > row.list_usd ? '≥ ' : ''}${fmtUsd(row.list_usd)}`
    return [
      jsxs('td', {
        className: 'py-1.5 pr-3',
        children: [
          jsx('div', { children: row.name }),
          subtitle ? jsx('div', { className: 'text-[0.625rem] text-(--ui-text-quaternary)', children: subtitle }) : null
        ].filter(Boolean)
      }),
      jsx('td', { className: 'py-1.5 pr-3 text-right tabular-nums', children: fmtTokens(row.tokens) }),
      jsx('td', { className: 'py-1.5 pr-3 text-right tabular-nums text-(--ui-text-tertiary)', children: String(row.calls || 0) }),
      jsx('td', {
        className: cn('py-1.5 pr-3 text-right tabular-nums',
          row.billed_usd == null ? 'text-(--ui-text-quaternary)' : ''),
        children: row.billed_usd == null ? t('unknown') : fmtUsd(row.billed_usd)
      }),
      jsx('td', {
        className: cn('py-1.5 pr-3 text-right tabular-nums',
          row.list_usd == null ? 'text-(--ui-warning)' : ''),
        children: list
      }),
      jsx('td', { className: 'py-1.5 pr-3 text-right tabular-nums text-(--ui-accent)', children: fmtUsd(row.basis_usd) }),
      jsx('td', {
        className: cn('py-1.5 text-right text-[0.625rem]',
          row.status === 'complete' ? 'text-(--ui-text-quaternary)' : 'text-(--ui-warning)'),
        children: t(`status_${row.status}`) || row.status
      })
    ]
  }
  return jsxs('table', {
    className: 'w-full text-xs',
    children: [
      jsx('thead', {
        children: jsx('tr', {
          children: head.map((label, i) =>
            jsx('th', {
              className: cn('pb-1.5 font-medium text-(--ui-text-quaternary)',
                i === 0 ? 'pr-3 text-left' : i === head.length - 1 ? 'text-right' : 'pr-3 text-right'),
              children: label
            }, label)
          )
        })
      }),
      jsx('tbody', {
        children: rows.map((row, i) =>
          jsx('tr', { className: 'border-b border-(--ui-stroke-secondary) align-top', children: cells(row) }, `${i}`)
        )
      })
    ]
  })
}

function reconciliationText(t, r) {
  if (!r || !r.status) return ''
  if (r.status === 'no_baseline') return t('noBaseline')
  if (r.status === 'state_db_unavailable') return t('stateUnavailable')
  if (r.delta_tokens == null) return ''
  if (r.delta_tokens === 0) return t('noGrowth')
  if (r.gap_tokens > 0) return t('reconcileGap', fmtTokens(r.gap_tokens), fmtTokens(r.delta_tokens))
  if (r.status === 'overcount') return t('reconcileOver', fmtTokens(Math.abs(r.gap_tokens)))
  return t('reconciled', fmtTokens(r.captured_tokens), fmtTokens(r.delta_tokens))
}

function LegacyAllHermesPage({ range }) {
  const t = usePluginI18n(ID)
  const view = useValue($view)
  const group = useValue($group)
  const basis = useValue($basis)
  const days = RANGE_DAYS[range] || 30
  const { data, error, isLoading, isFetching, refetch } = useQuery({
    ...backendQuery(days, basis),
    refetchInterval: 60_000
  })

  const totals = data && data.totals ? data.totals : null
  const rows = data && Array.isArray(data[`by_${group}`]) ? data[`by_${group}`] : []
  const rateCard = data && data.rate_card ? data.rate_card : null

  const header = jsxs('div', {
    className: 'flex flex-wrap items-center justify-between gap-3',
    children: [
      jsx('h1', { className: 'text-base font-semibold', children: t('allHermesTitle') }),
      jsxs('div', {
        className: 'flex flex-wrap items-center gap-2',
        children: [jsx(ViewToggle, { t, view }), jsx(RangeToggle, { t, range }), jsx(BasisToggle, { t, basis }), jsx(CloseButton, { t })]
      })
    ]
  })

  if (error) {
    return jsxs('div', {
      className: 'mx-auto flex w-full max-w-3xl flex-col gap-4 p-6',
      children: [
        header,
        jsxs('div', {
          className: 'rounded-md border border-(--ui-warning) p-4 text-xs',
          children: [
            jsx('div', { className: 'mb-2 font-medium text-(--ui-warning)', children: t('backendUnavailable') }),
            jsx('div', { className: 'mb-3 text-(--ui-text-tertiary)', children: String(error.message || error) }),
            jsxs('div', {
              className: 'flex flex-wrap gap-2',
              children: [
                jsx(Button, { onClick: () => refetch(), size: 'sm', variant: 'outline', children: t('backendRetry') }),
                jsx(Button, { onClick: () => $view.set(VIEW_DESKTOP), size: 'sm', variant: 'ghost', children: t('backendUseDesktop') })
              ]
            })
          ]
        })
      ]
    })
  }

  if (isLoading && !data) {
    return jsxs('div', {
      className: 'mx-auto flex w-full max-w-3xl flex-col gap-4 p-6',
      children: [header, jsx('div', { className: 'text-xs text-(--ui-text-quaternary)', children: t('backendLoading') })]
    })
  }

  const billingMix = totals && totals.billing_tokens
    ? Object.entries(totals.billing_tokens)
        .filter(([, n]) => n > 0)
        .map(([kind, n]) => `${t(`class_${kind}`)} ${fmtTokens(n)}`)
        .join(' · ')
    : ''
  const rec = data && data.recording ? data.recording : null
  const recon = data && data.reconciliation ? data.reconciliation : null
  const baseline = data && data.baseline ? data.baseline : null
  const baselineTotals = baseline && baseline.totals ? baseline.totals : null
  const eventInfo = data && data.events ? data.events : null
  const coverage = totals ? Math.round((totals.coverage || 0) * 1000) / 10 : 0

  return jsxs('div', {
    className: 'mx-auto flex w-full max-w-3xl flex-col gap-4 p-6',
    children: [
      header,
      jsx('div', { className: 'text-xs text-(--ui-text-quaternary)', children: t('allHermesHint') }),
      totals
        ? jsxs('div', {
            className: 'grid grid-cols-2 gap-3 sm:grid-cols-4',
            children: [
              jsx(Stat, {
                label: t('statList'),
                value: totals.list_usd == null ? '—' : fmtUsd(totals.list_usd),
                hint: t('perCallExact')
              }),
              jsx(Stat, {
                label: t('statBilled'),
                value: totals.billed_usd == null ? '—' : fmtUsd(totals.billed_usd),
                hint: billingMix || t('billedPartial'),
                warn: totals.billed_usd == null
              }),
              jsx(Stat, {
                label: t('statCalls'),
                value: String(totals.calls || 0),
                hint: eventInfo ? t('eventsLine', eventInfo.calls, eventInfo.failures, eventInfo.missing_usage) : null
              }),
              jsx(Stat, {
                label: t('statCoverage'),
                value: `${coverage}%`,
                hint: totals.unpriced_tokens ? t('unpricedTokens', fmtTokens(totals.unpriced_tokens)) : null,
                warn: coverage < 99
              })
            ]
          })
        : null,
      jsxs('div', {
        className: 'flex flex-col gap-1 text-[0.6875rem] text-(--ui-text-quaternary)',
        children: [
          jsx('div', {
            children: rec && rec.since
              ? t('recordedSince', String(rec.since).slice(0, 19).replace('T', ' '))
              : t('notRecordingYet')
          }),
          recon
            ? jsx('div', {
                className: recon.gap_tokens > 0 ? 'text-(--ui-warning)' : '',
                children: reconciliationText(t, recon)
              })
            : null,
          eventInfo
            ? jsx('div', {
                children: t('eventsLine', eventInfo.calls, eventInfo.failures, eventInfo.missing_usage)
              })
            : null
        ].filter(Boolean)
      }),
      rateCard
        ? jsx('div', {
            className: 'text-[0.6875rem] text-(--ui-text-quaternary)',
            children: t('rateCard', rateCard.source, rateCard.as_of ? String(rateCard.as_of).slice(0, 10) : '')
          })
        : null,
      jsx(SegmentedControl, {
        onChange: v => $group.set(v),
        options: GROUPINGS.map(id => ({ id, label: t(`group_${id}`) })),
        value: group
      }),
      rows.length
        ? jsx(GroupTable, { group, rows, t })
        : jsx('div', {
            className: 'rounded-md border border-(--ui-stroke-secondary) p-6 text-center text-xs text-(--ui-text-quaternary)',
            children: t('allHermesEmpty')
          }),
      data && data.unpriced && data.unpriced.length
        ? jsxs('div', {
            className: 'rounded-md border border-(--ui-warning) p-3 text-xs',
            children: [
              jsx('div', { className: 'mb-1 font-medium text-(--ui-warning)', children: t('unpricedTitle') }),
              ...data.unpriced.slice(0, 6).map((u, i) =>
                jsx('div', { className: 'text-(--ui-text-tertiary)', children: t('unpricedLine', u.provider, u.model, fmtTokens(u.tokens), u.reason) }, `${i}`)
              )
            ]
          })
        : null,
      baselineTotals
        ? jsxs('details', {
            className: 'rounded-md border border-(--ui-stroke-secondary) p-3 text-xs',
            children: [
              jsx('summary', { className: 'cursor-pointer font-medium', children: t('baselineTitle') }),
              jsxs('div', {
                className: 'mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3',
                children: [
                  jsx(Stat, { label: t('baselineTokens'), value: fmtTokens(baselineTotals.tokens) }),
                  jsx(Stat, {
                    label: t('statList'),
                    value: baselineTotals.list_usd == null ? '—' : `${fmtUsd(baselineTotals.list_usd)} est.`
                  }),
                  jsx(Stat, {
                    label: t('statBilled'),
                    value: baselineTotals.billed_usd == null ? '—' : fmtUsd(baselineTotals.billed_usd),
                    warn: !baselineTotals.billed_complete
                  })
                ]
              }),
              baseline.note
                ? jsx('p', { className: 'mt-2 text-[0.6875rem] text-(--ui-text-quaternary)', children: baseline.note })
                : null,
              baseline.by_route && baseline.by_route.length
                ? jsx('div', {
                    className: 'mt-2 flex flex-col gap-0.5 text-[0.6875rem] text-(--ui-text-tertiary)',
                    children: baseline.by_route.slice(0, 5).map((r, i) =>
                      jsx('div', {
                        children: t('baselineRouteLine', r.name, fmtTokens(r.tokens),
                          r.list_usd == null ? t('unpriced') : fmtUsd(r.list_usd),
                          r.billed_usd == null ? t('unknown') : fmtUsd(r.billed_usd))
                      }, `${i}`)
                    )
                  })
                : null
            ]
          })
        : null,
      data && data.limits && data.limits.length
        ? jsxs('details', {
            className: 'rounded-md border border-(--ui-stroke-secondary) p-3 text-[0.6875rem] text-(--ui-text-quaternary)',
            children: [
              jsx('summary', { className: 'cursor-pointer', children: t('limitsTitle') }),
              jsx('ul', {
                className: 'mt-2 list-disc space-y-1 pl-4',
                children: data.limits.map((line, i) => jsx('li', { children: line }, `${i}`))
              })
            ]
          })
        : null,
      jsxs('div', {
        className: 'flex flex-wrap items-center gap-2',
        children: [
          jsx(Button, { disabled: isFetching, onClick: () => refetch(), size: 'sm', variant: 'outline', children: t('refresh') }),
          jsx(Button, { onClick: () => $view.set(VIEW_DESKTOP), size: 'sm', variant: 'ghost', children: t('backendUseDesktop') })
        ]
      })
    ].filter(Boolean)
  })
}

/* ------------------------------------------------------------ memberships */

/**
 * Membership pane state. Kept in atoms like the rest of the file so a commit
 * re-renders without adding React hooks the host may not export.
 */
const $membershipDraft = atom(null)
const $customPlanDraft = atom(null)
const $exhaustionDraft = atom(null)
const $membershipEntitlementDraft = atom(null)
const $membershipNotice = atom(null)
const $membershipBusy = atom('')
/** Read account usage through Hermes on the next fetch. */
const $membershipNative = atom(false)
const $membershipAttentionOnly = atom(false)
// Expanded account rows, keyed by account id. Pure UI state, but still
// stamped with the identity it belongs to so a switch never shows one
// backend's rows expanded under another's accounts.
const $membershipExpanded = atom({ origin: null, ids: [] })
// Pending attention navigation: { origin, accountId, issue, group, focus,
// windowId }. Set by an Overview or Memberships attention action, consumed by
// MembershipsPage once the target identity's accounts are on screen. Stamped
// with the connection identity so a gateway/profile switch discards it.
const $membershipTarget = atom(null)
// Groups the user has collapsed while their draft is active. A draft opens
// its group, but the user's own toggle always wins afterwards: re-renders
// never snap a collapsed group back open, and draft values are untouched.
// Without a draft the groups are fully uncontrolled.
const membershipGroupClosed = new Set()
function membershipGroupOpen(accountId, group, active) {
  const key = `${accountId}:${group}`
  if (!active) { membershipGroupClosed.delete(key); return {} }
  if (membershipGroupClosed.has(key)) return {}
  return { open: true }
}
function membershipGroupToggled(accountId, group, open) {
  const key = `${accountId}:${group}`
  if (open) membershipGroupClosed.delete(key)
  else membershipGroupClosed.add(key)
}
/**
 * Last good account payload. A refetch with a new query key unmounts the cards
 * for a moment; rendering from this keeps the pane from flashing "no memberships"
 * and stops a click racing an empty list.
 */
const $membershipSnapshot = atom(null)

// A membership read belongs to one gateway, one profile *and* one activation of
// that gateway. These are the identity of the read: the SDK routes every
// ctx.rest call with the ambient connection/profile, so a result cached or
// started under one identity must never be served or accepted under another.
// `host.state.*` are readonly atoms; older builds may not expose them, hence the
// fallbacks.
const $scopeConnection = host?.state?.connectionId || atom(null)
const $scopeProfile = host?.state?.profile || atom('default')

/**
 * `gatewayActivationEpoch()` is a function, not an atom, so it cannot be a
 * dependency on its own. The host's gateway atom does change when an activation
 * completes in common cases. Listeners and a lifecycle-scoped interval keep
 * the captured generation in step even when socket state stays unchanged.
 */
const $membershipActivation = atom(gatewayActivationEpoch())
for (const signal of [host?.state?.gateway, $scopeConnection, $scopeProfile]) {
  if (signal?.listen) signal.listen(() => $membershipActivation.set(gatewayActivationEpoch()))
}

/** `${connection}|${profile}` — the scope a membership read belongs to. */
const membershipScopeOf = (connectionId, profile) =>
  `${connectionId || 'local'}|${profile || 'default'}`

/** `${scope}#${activation}` — the identity a read, draft or write belongs to. */
const membershipIdentityOf = (connectionId, profile, activation) =>
  `${membershipScopeOf(connectionId, profile)}#${activation ?? 0}`

const $membershipScope = computed([$scopeConnection, $scopeProfile], membershipScopeOf)

const $membershipIdentity = computed(
  [$scopeConnection, $scopeProfile, $membershipActivation],
  membershipIdentityOf
)

const membershipScopeNow = () => membershipScopeOf($scopeConnection.get(), $scopeProfile.get())
const membershipIdentityNow = () =>
  membershipIdentityOf($scopeConnection.get(), $scopeProfile.get(), gatewayActivationEpoch())

/** True only while the captured identity is still the one the pane is showing. */
const membershipIdentityCurrent = identity => identity === membershipIdentityNow()

/**
 * Kept for callers that compare a scope plus a generation separately. The pane
 * itself uses `membershipIdentityCurrent`, which folds both into one string.
 */
const membershipScopeCurrent = (scope, generation) =>
  membershipScopeNow() === scope && gatewayActivationEpoch() === generation

/**
 * Bounded, redacted request log. Method, relative path, status, identity, plugin
 * id and generation only — never headers, tokens, bodies or account contents.
 */
const MEMBERSHIP_DIAGNOSTIC_LIMIT = 12
const membershipDiagnostics = []
function membershipTrace(entry) {
  membershipDiagnostics.unshift({
    at: new Date().toISOString(),
    plugin: ID,
    method: String(entry.method || 'GET').toUpperCase(),
    path: String(entry.path || ''),
    status: entry.status ?? null,
    scope: String(entry.identity || entry.scope || ''),
    generation: entry.generation ?? null,
    outcome: String(entry.outcome || '')
  })
  membershipDiagnostics.length = Math.min(membershipDiagnostics.length, MEMBERSHIP_DIAGNOSTIC_LIMIT)
}

/* ---- state that always belongs to exactly one identity ------------------- */

/** A notice is only ever shown in the identity that produced it. */
function setMembershipNotice(identity, tone, text, operation = null, accountId = null, compatibility = false) {
  if (!membershipIdentityCurrent(identity) || (operation && !membershipOperationCurrent(identity, operation))) return false
  $membershipNotice.set({ tone, text, origin: identity, accountId, compatibility })
  return true
}

let membershipOperationSerial = 0
let latestMembershipOperation = null
function membershipOperationCurrent(identity, operation) {
  return membershipIdentityCurrent(identity) && latestMembershipOperation === operation
}

function claimMembershipBusy(identity, key) {
  if (!membershipIdentityCurrent(identity)) return null
  const held = $membershipBusy.get()
  if (held && held.origin === identity) return null
  const operation = ++membershipOperationSerial
  latestMembershipOperation = operation
  $membershipBusy.set({ key, origin: identity, operation })
  if ($membershipNotice.get()?.origin === identity) $membershipNotice.set(null)
  return operation
}

function releaseMembershipBusy(identity, operation) {
  const held = $membershipBusy.get()
  // An old scope finishing must not clear a new scope's spinner.
  if (held && held.origin === identity && held.operation === operation) $membershipBusy.set(null)
}

/** The busy key the current identity may show, or '' when it holds none. */
function membershipBusyKey(busy, identity) {
  return busy && busy.origin === identity ? busy.key : ''
}

